=図鑑_敵キャラデータ設定セクション by nwapeg

図鑑の敵キャラの項に表示する内容を設定します。
解説のスクロールを実装した際に、制御文字の描画が不可能になりました。

==更新履歴
Date     Version Author Comment
13/07/24 0.2.1   Foo    出現場所配列の追加
13/07/21 0.2.0   Foo    エネミー画像設定の追加
12/06/08 0.1.0   nwapeg 試作

=end

