      "enigmatic Apoptosis, Shinifa is a",
      "very mysterious type.",
      "",
      "Artist: xelvy",
    ],
    138 => [
      "A shadow monster of unknown lineage",
      "living inside the tower of another",
      "world. She appears to have been",
      "birthed from the residual magic",
