      "",
      "Artist: Delphinus",
    ],
    567 => [
      "One of the Seven Archangels",
      "created by the Goddess Ilias from",
      "the Angelic Dominion during the",
      "Great Monster Wars, she is known",
      "by the epithet Holy Lily of",
      "Compassion. Renowned as the",
      "Dominion's most skilled healer,",
      "her mastery over support and",
      "enhancement magic is unparalleled.",
      "Additionally, she excels in",
      "whip-based combat techniques,",
      "making her a formidable force",
      "among the Dominion's elite. She",
      "oversees Sabasa, a vast agrarian",
      "state responsible for the realm's",
      "food production. She pioneered the",
      "large-scale farming system that",
      "employs clone workers and has",
      "garnered immense praise from the",
      "Goddess Ilias herself for this",
      "achievement. Her ambition extends",
      "even further, with plans to",
      "selectively clone elite citizens",
      "for broader applications.",
      "",
      "Contrary to her epithet, she is",
      "ruthlessly ambitious and",
      "exceedingly cruel. She views",
      "others merely as tools to further",
      "her own success. Her hunger",
      "extends to men, whom she handpicks",
      "and brings to her bedroom,",
      "draining them of their semen until",
      "death, indulging in the pleasure",
      "it brings her.",
      "",
      "Artist: xelvy",
    ],
    568 => [
      "Archangels specialized for close",
      "combat that have been mass-produced.",
      "They are the highest-ranked of the",
      "soldier types, possessing combat",
      "prowess far beyond the compare of",
      "ordinary Angel Soldiers. They are",
      "ferocious with incredibly keen",
      "senses for battle, but their ability",
      "to control holy energy is inferior",
      "to other archangels, and they have a",
      "very strong tendency to rush headlong",
      "into situations since they also",
      "dislike complex thinking. Since they",
      "only cost half as many resources to",
      "produce compared to other archangels,",
      "they were mass-produced in",
      "preparation for the Second Great",
      "Monster Wars. They are deployed",
      "across each city in large numbers as",
      "elite guards of their defense forces.",
      "",
      "Since they have incredibly strong",
      "fighting instincts, they also have",
      "incredibly powerful sex drives. They",
      "are said to take pleasure in raping",
      "men who surrender to her, and will",
      "sometimes even rape them to death in",
      "bouts of sadism. The Giriels have",
      "deep respect for Uriela of the Seven",
      "Archangels due to their nature which",
      "regards power as absolute, and so",
      "they aspire to be deployed at Grand",
      "Noah. On the contrary, they get along",
      "poorly with the resourceful types",
      "like Raphaela and Gabriela.",
      "",
      "Artist: raichi",
    ],
    569 => [
      "Strange-looking chimeric soldiers",
      "that have been mass-produced for the",
      "purpose of taking over human towns by",
      "force. Machine technology was used",
      "extensively in their creation, as",
      "their bodies appear to be over 80%",
      "mechanical. They have brutal and",
      "ruthless personalities, and derive",
      "the greatest joy in oppressing",
      "others. The Angelic Dominion was",
      "offered their design data from the",
      "Alliance of Wisdom, and began",
      "producing them en-masse. While",
      "originally an invasion-type, they",
      "have been deployed in large numbers",
      "primarily in Grand Noah, which",
      "neighbors Esta, as a city defense",
      "force in preparation for attacks from",
      "other worlds. It also appears that a",
      "significant number of them have been",
      "assigned to the Great Prison of",
      "Grangold.",
      "",
      "They can generate shocks with a",
      "special unit integrated into their",
      "right arms, and its vacuum function",
      "allows it to also serve as a semen-",
      "extraction tool. One of their roles",
      "appears to be harvesting semen from",
      "humans in the areas they subjugate,",
      "storing it in their special tanks.",
      "Should they capture a man, they will",
      "extract every last drop of semen out",
      "of him. They do not acknowledge",
      "surrender and often keep sucking men",
      "until they die, but even the men who",
      "are taken prisoner aren't any more",
      "fortunate. In such cases, a hell of",
      "semen extraction undoubtedly awaits",
      "them.",
      "",
      "Artist: xelvy",
    ],
    570 => [
      "An angel belonging to the seventh",
      "circle of the nine in the angel",
      "hierarchy (Principality) who is",
      "trained in both swordsmanship and",
      "hand-to-hand combat. While she",
      "possesses incredibly high strength as",
      "well as blazing fighting instincts,",
      "she is self-disciplined and doesn't",
      "stoop to vulgarity. They were",
      "originally created to be the elite",
      "guard for Uriela of the Seven",
      "Archangels, but have been deployed in",
      "every country after a flood of",
      "requests for them due to their",
      "excellent performance. They are",
      "presently stationed at key locations",
      "across the Angelic Dominion. Having",
      "endured Uriela's rigorous military",
      "training, the Sabiriels are said to",
      "be valued as the cornerstones of city",
      "defense. In addition, many of them",
      "are also Colosseum fighters,",
      "entertaining the masses as stars of",
      "the arena.",
      "",
      "When she rapes a man, she treats it",
      "like an extension of her grappling",
      "techniques by pinning him down as she",
      "violates him. No man has ever been",
      "able to withstand her strength and",
      "muscles, and they end up having their",
      "semen wrung out as they're",
      "helplessly pinned down. Many",
      "fighters at the Colosseum have been",
      "raped by a Sabiriel in full public",
      "display, and it is said that a great",
      "number of men let themselves be raped",
      "by them on purpose.",
      "",
      "Artist: makiya",
    ],
    571 => [
      "An angel belonging to the seventh",
      "circle of the nine in the angel",
      "hierarchy (Principality) who is",
      "trained in both swordsmanship and",
      "hand-to-hand combat. While she",
      "possesses incredibly high strength as",
      "well as blazing fighting instincts,",
      "she is self-disciplined and doesn't",
      "stoop to vulgarity. They were",
      "originally created to be the elite",
      "guard for Uriela of the Seven",
      "Archangels, but have been deployed in",
      "every country after a flood of",
      "requests for them due to their",
      "excellent performance. They are",
      "presently stationed at key locations",
      "across the Angelic Dominion. Having",
      "endured Uriela's rigorous military",
      "training, the Sabiriels are said to",
      "be valued as the cornerstones of city",
      "defense. In addition, many of them",
      "are also Colosseum fighters,",
      "entertaining the masses as stars of",
      "the arena.",
      "",
      "When she rapes a man, she treats it",
      "like an extension of her grappling",
      "techniques by pinning him down as she",
      "violates him. No man has ever been",
      "able to withstand her strength and",
      "muscles, and they end up having their",
      "semen wrung out as they're",
      "helplessly pinned down. Many",
      "fighters at the Colosseum have been",
      "raped by a Sabiriel in full public",
      "display, and it is said that a great",
      "number of men let themselves be raped",
      "by them on purpose.",
      "",
      "Artist: makiya",
    ],
    572 => [
      "An elven monster swordswoman renowned",
      "as one of the most powerful sword-",
      "fighters in the Angelic Dominion. Her",
      "sword flashes surpass those even from",
      "combat-specialized angels such as the",
      "Sabiriels, and despite being a",
      "monster, her fame has resounded",
      "across the entire Dominion. After",
      "gaining a citizenship in Grand Noah,",
      "a nation that promotes martial",
      "prowess, she has focused solely on",
      "challenging stronger opponents, and",
      "has kept her distance from the",
      "monster resistance groups. Her basis",
      "for this appears to be her belief",
      "that the weak deserve to be",
      "oppressed, and that the world is",
      "ultimately ruled by the strong.",
      "Her homeland appears to be Fairy's",
      "Island, but nothing else is known",
      "about her birth or how she became a",
      "monster swordswoman.",
      "",
      "She is also a regular at the",
      "Colosseum who has bested many",
      "contestants, and following Colosseum",
      "customs, she rapes defeated males.",
      "The men are especially afraid of",
      "her sitting on their faces with her",
      "large ass as she mounts them cowgirl",
      "style, whispering \"I'm going to be",
      "crushed by Fernandez's huge ass\"",
      "with both dread and longing.",
      "",
      "Artist: UN_DO",
    ],
    573 => [
      "One of the Seven Archangels",
      "created by the Goddess Ilias from",
      "the Angelic Dominion during the",
      "Great Monster Wars, she is a",
      "living embodiment of combat, her",
      "entire body equipped with",
      "devastating weaponry. Her",
      "overwhelming prowess in battle is",
      "legendary, said to rival even",
      "Micaela, the strongest in the",
      "Dominion, when it comes to sheer",
      "physical might. Her strength",
      "resonates across all of the",
      "Dominion, inspiring warriors far",
      "and wide to revere her as an ideal",
      "to strive toward.",
      "Tasked with governing Grand Noah,",
      "she delegates administrative",
      "duties to her highly competent",
      "subordinates, trusting their",
      "judgment. Her sharp eye for talent",
      "ensures that politics in Grand",
      "Noah flow smoothly under her rule.",
      "She promotes martial strength",
      "above all else, respecting even",
      "monsters if they prove themselves",
      "strong. Conversely, she has no",
      "regard for the weak, dismissing",
      "them entirely. This philosophy",
      "makes the region's development",
      "especially harsh, with",
      "second-class citizens reportedly",
      "treated worse than slaves.",
      "",
      "When it comes to violating men,",
      "Uriela is as relentless and brutal",
      "as she is in battle. However, she",
      "only targets men of exceptional",
      "fortitude, ensuring she never",
      "unintentionally kills them through",
      "overexertion. That said, no matter",
      "how resilient a man may be,",
      "enduring Uriela's rape will",
      "inevitably leave him completely",
      "drained, unable to stand or move",
      "for some time.",
      "",
      "Artist: xelvy",
    ],
    574 => [
      "An angel belonging to the sixth",
      "circle of the nine in the angel",
      "hierarchy (Power). Her primary duty",
      "is to manage the ecology and regulate",
      "the numbers of all insect species in",
      "the Angelic Dominion. She possesses",
      "the genes of every insect that exists",
      "in the world, and should the balance",
      "of any individual species sharply",
      "decline, she is able to birth many",
      "insects by fertilizing herself with a",
      "male's sperm. To accomplish this task",
      "of ecological conservation, she",
      "constantly needs to secure men for",
      "seeding purposes.",
      "",
      "The various insect genes she",
      "possesses are manifested all over her",
      "body, making her look so bizarre that",
      "she is often mistaken for a monster.",
      "These insect characteristics also",
      "give her great fighting capabilities,",
      "and she is able to lead a fighting",
      "force in the event of a rebellion.",
      "During such times, she will quickly",
      "capture and secure any sinners who",
      "might be suitable for reproduction.",
      "",
      "Artist: Setouchi",
    ],
    575 => [
      "An angel belonging to the fifth",
      "circle of the nine in the angel",
      "hierarchy (Virtue). Her primary duty",
      "is to wrap the souls of the dead (who",
      "were unable to leave their body for",
      "some reason) in cocoons using her",
      "silk, and send them off to Heaven.",
      "Despite being a high-ranked angel,",
      "the nature of her duty requires her",
      "to frequently descend to the surface",
      "world",
      "",
      "The \"Thread of Eternity\" she shoots",
      "out from her body is imbued with holy",
      "energy, and has the effect of putting",
      "the wrapped-up soul into a trance as",
      "it ascends to Heaven. In the unlikely",
      "event a living human should get",
      "rolled up in her thread, their entire",
      "body will relax from the delightful",
      "pleasure, causing women to repeatedly",
      "climax while men exhaust themselves",
      "ejaculating their semen",
      "uncontrollably. She normally isn't",
      "permitted to do this, but it's a",
      "different story if the human is a",
      "sinner. While she isn't blessed with",
      "opportunities to exercise divine",
      "punishments due to her different",
      "jurisdiction, she secretly harbors",
      "desires to someday go out and",
      "subjugate sinners, wrap them in her",
      "\"Thread of Eternity\", and send them",
      "off to Heaven.",
      "",
      "Artist: Delphinus",
    ],
    576 => [
      "One of the Seven Archangels",
      "created by the Goddess Ilias from",
      "the Angelic Dominion during the",
      "Great Monster Wars and overseer of",
      "the Grangold Maximum Security",
      "Prison, where notorious criminals",
      "and political prisoners are",
      "confined. Designed with undead",
      "traits, her body possesses an",
      "extraordinary regenerative",
      "ability, making her nearly",
      "immortal. While her usual focus is",
      "on managing the prison, she wields",
      "exceptional skill in scythe",
      "techniques and magical power,",
      "ranking among the Dominion's most",
      "formidable fighters. As a warden,",
      "she also carries out torture and",
      "executions, not out of cruelty,",
      "but simply as part of her duties.",
      "She strictly adheres to rules and",
      "regulations, maintaining a",
      "serious, no-nonsense demeanor with",
      "zero tolerance for leniency.",
      "Despite her stern nature, both",
      "toward herself and her",
      "subordinates, she commands a",
      "surprising level of respect from",
      "those who serve under her, as she",
      "is fair and refrains from imposing",
      "unreasonable demands.",
      "",
      "Her genitals are equipped with",
      "multiple biological torture",
      "mechanisms designed to inflict",
      "intense torment on the genitals of",
      "male prisoners. She administers",
      "severe punishments and, at times,",
      "even executes prisoners using this",
      "torturous physiology. It's said",
      "that when a man finally succumbs,",
      "Sariela's vagina is left",
      "overflowing with his dying sperm.",
      "",
      "Artist: xelvy",
    ],
    577 => [
      "An angel belonging to the sixth",
      "circle of the nine in the angel",
      "hierarchy (Power). She has been",
      "given the role of judging sinners in",
      "the Angelic Dominion, but she",
      "specializes in punishing those",
      "committing the sin of gluttony. She",
      "disguises herself as a fruit to test",
      "the souls of sinners sent to the",
      "Dominion, and devours any who try to",
      "eat her.",
      "After the Great Monster Wars ended",
      "and the entire world was transformed",
      "into the Angelic Dominion, she was",
      "appointed as a guard at the prison",
      "city of Grangold. She still strongly",
      "associates the prisoners she",
      "monitors as sinners, and carries out",
      "predatory punishments on them",
      "accordingly.",
      "",
      "In times of emergency, she may be",
      "called upon for her fighting",
      "strength and use her predatory",
      "abilities to mercilessly devour the",
      "bodies and souls of the Goddess'",
      "enemies. She is an extremely cruel",
      "and greedy angel who is sometimes",
      "made fun of by other angels for",
      "committing the sin of gluttony",
      "herself.",
      "",
      "Artist: Delphinus",
    ],
    578 => [
      "A chimeric monster created by the",
      "Angelic Dominion for the purpose of",
      "cultivating test subjects. She was",
      "completed at the Remina Laboratory",
      "using technology unique to the",
      "Dominion based on data provided by",
      "the Alliance of Wisdom. Since she is",
      "capable of cultivating various",
      "organisms within her body in an",
      "ideal environment, she is highly",
      "valued as a chimeric monster that",
      "supports research and production.",
      "It's said that the mass-production of",
      "various types of chimeric monsters",
      "using data provided by the Alliance",
      "of Wisdom was made possible solely by",
      "the existence of the Chimera Plants.",
      "",
      "While not originally designed for",
      "combat, her capturing abilities and",
      "sturdiness are exceptional, and spare",
      "individuals may sometimes be called",
      "upon to seize intruders. She also",
      "possesses the ability to harvest the",
      "semen of male specimens she has",
      "taken into her body, and can squeeze",
      "out the sperm of her captured target",
      "until he is exhausted.",
      "",
      "Artist: Setouchi",
    ],
    579 => [
      "An angel belonging to the fifth",
      "circle of the nine in the angel",
      "hierarchy (Virtue). She has the",
      "ability to reincarnate the souls of",
      "both the deceased and the living into",
      "a new existence. It is possible for",
      "her to reincarnate someone favored by",
      "the Goddess with all of their genetic",
      "information the same, or reincarnate",
      "the soul of someone undesirable to",
      "her into a completely different",
      "person. Due to this characteristic,",
      "she has often been given special",
      "orders directly from by Ilias.",
      "",
      "When reincarnating someone who is",
      "still alive, Revel dissolves their",
      "physical body inside of her. The",
      "pleasure they feel when she does this",
      "to them is said to be so incredible",
      "that they tremble with delight from",
      "being reincarnated.",
      "",
      "Artist: Delphinus",
    ],
    580 => [
      "An artificial spirit created through",
      "machine technology that has the power",
      "to control fire. She is stationed in",
      "Gold Volcano in the Gold region ruled",
      "ruled by Sariela, and is said to be",
      "responsible for the movement of fire.",
      "Her abilities are comparable to",
      "Salamander's, but she requires an",
      "enormous amount of life energy to",
      "maintain. Consequently, many",
      "criminals are taken to Gold Volcano",
      "to replenish her energy through",
      "sexual intercourse. That fact is",
      "widely known within Grangold Prison,",
      "where they are \"used as fuel for",
      "Gigamander\".",
      "",
      "She has a very belligerent and",
      "violent personality, and is extremely",
      "sadistic as well. Men who are",
      "offered to her are squeezed until",
      "they are completely drained, and it",
      "is said that this semen squeezing is",
      "often used as a form of execution.",
      "While she normally isn't the type to",
      "be content with living in captivity,",
      "she actually enjoys her lava-filled",
      "surroundings more than anywhere else",
      "in the world, and has thus never made",
      "any attempt to escape.",
      "",
      "Artist: UN_DO",
    ],
    581 => [
      "One of the Next Dolls, the strongest",
      "chimeric monsters created by",
      "Promestein. Built to fight against",
      "Alma Elma of the Monster Lord's Four",
      "Heavenly Knights, she boasts",
      "tremendous speed. She is also able to",
      "freely manipulate wind, allowing her",
      "to counteract Alma Elma's wind magic.",
      "In addition, because her pleasure",
      "nerves had been removed, the",
      "succubus' pleasure attacks have",
      "absolutely no effect against her.",
      "",
      "Removing her pleasure nerves however,",
      "has resulted in significant negative",
      "effects to her emotions, and her mind",
      "appears to be unstable. Her tendency",
      "to derive joy from excessive cruelty",
      "and violence towards others is also",
      "an effect of this emotional",
      "instability. Her body was made",
      "lighter to optimize speed",
      "performance, but this came at the",
      "cost of her defensive ability. She",
      "can easily overwhelm her opponent",
      "with sheer agility if they are also",
      "a speed-type like herself, but she",
      "would no doubt be at a serious",
      "disadvantage against a highly-skilled",
      "warrior-type opponent.",
      "With that said, keeping up with",
      "Hainuwele's velocity is nearly",
      "impossible, and unless someone is a",
      "warrior who has mastered both speed",
      "and technique, they will likely fall",
      "before her speed.",
      "",
      "Artist: Thomas",
    ],
    582 => [
      "An individual from a mysterious",
      "group known as the \"Moon-Dwellers\",",
      "who all bear an identical face and",
      "appearance with the exception of",
      "their commander. All of them are",
      "expert swordswomen possessing combat",
      "capabilities that average angel",
      "soldiers are no match for. They",
      "invade from the moon in units using",
      "unknown dropships, and whenever they",
      "descend upon towns and village under",
      "angel control, they are said to",
      "wreak significant havoc. They",
      "primarily target only angels, and",
      "while they avoid harming other",
      "residents, they don't cooperate or",
      "coordinate with the resistance",
      "organizations on the surface,",
      "carrying out repeated assaults as an",
      "independent combat group.",
      "",
      "Their true identities are believed to",
      "be clones, but the reason why their",
      "base is on the moon is completely",
      "unknown. Despite there being a gag",
      "order in place regarding the topic",
      "of the \"Moon-Dwellers\", their",
      "existence is being whispered about",
      "amongst the general public.",
      "",
      "Artist: frfr",
    ],
    583 => [
      "A female warrior who appears to be",
      "an officer-ranked member of the",
      "Moon-Dwellers. While she has the",
      "same face as all of the other",
      "individuals, her hairstyle and",
      "armaments are different, implying",
      "that she is of a higher rank than",
      "the average soldier. Her combat",
      "abilities are also remarkably",
      "superior compared to average",
      "soldiers, possessing such power that",
      "even mid-ranking angels are no match",
      "for her. She also has such excellent",
      "judgement and tactical insight that",
      "despite having conducted repeated",
      "raids, not a single one of the Moon-",
      "Dwellers has ever been captured.",
      "",
      "Three other officer-ranked members",
      "have also been identified, but there",
      "have been no cases of them being",
      "dispatched together at the same",
      "battlefield. An angel assault on the",
      "moon had also been planned, but with",
      "at least four warriors of this class",
      "present, the Seven Archangels would",
      "need to be deployed, so it had been",
      "postponed.",
      "",
      "Artist: frfr",
    ],
    584 => [
      "A chimeric monster created from",
      "Promestein's research. By",
      "manipulating the embryos of soft-",
      "bodied slug monsters, she had",
      "succeeded in causing tongue-shaped",
      "organs to manifest all over the",
      "chimera's body. Every tongues on her",
      "body is capable of tasting and",
      "secreting saliva, and they are also",
      "flexible to some degree. Her vitality",
      "and physical abilities have also",
      "improved drastically, and she has no",
      "obvious mental abnormalities apart",
      "from food cravings. While she was an",
      "early embryo manipulated-based",
      "chimeric monster, she is considered",
      "to have a high degree of perfection",
      "due to the simplicity of her",
      "procedure.",
      "",
      "She likes the bodily fluids of humans",
      "and monsters, and will lick both",
      "men's and women's bodies all over to",
      "absorb their sweat and saliva. Of",
      "course, the semen of human males is",
      "her favorite food, and should her",
      "prey be a man, she'll thoroughly lick",
      "his crotch to squeeze out his semen",
      "and ingest it with her tongues.",
      "Using her excellent tongue skills,",
      "she can easily force her prey",
      "ejaculate multiple times. In most",
      "cases she will lick her prey until",
      "he is completely dry, but if he has",
      "high-quality semen, she may keep her",
      "caught prey alive.",
      "",
      "Artist: Setouchi",
    ],
    585 => [
      "A chimeric monster created from",
      "Promestein's research. She was an",
      "early model created with a focus on",
      "enhancing reproductive ability, and",
      "was considered an experimental",
      "subject with the mass-production of",
      "chimeric monsters in mind for the",
      "future. The cells of the Beelzebub,",
      "a supposedly now-extinct ancient",
      "insect monster said to have",
      "astounding reproductive abilities,",
      "were incorporated into her.",
      "",
      "While the original purpose of her",
      "creation was solely to experiment",
      "with enhancing reproductive ability,",
      "since she also has the incredibly",
      "tough exoskeleton and extreme agility",
      "characteristic of insects, many of",
      "them are being mass-produced as",
      "simple production forces in",
      "anticipation of a second Great",
      "Monster Wars.",
      "",
      "She also has a very strong desire to",
      "breed, and will force herself upon",
      "any human male she sees and make him",
      "impregnate her. Sperm released into",
      "her oviduct will immediately be used",
      "for reproduction and fertilize the",
      "eggs in her abdomen. Men who have",
      "been thoroughly squeezed of their",
      "semen by her will usually be tossed",
      "away as no longer being useful, but",
      "if one has high-quality sperm, she",
      "may keep him as a reproductive",
      "partner.",
      "",
      "Artist: xelvy",
    ],
    586 => [
      "One of the earliest chimeric monsters",
      "created from Promestein's research.",
      "She was an embryo-manipulated",
      "technology demonstration type that",
      "displays maximized slug",
      "characteristics, successfully",
      "improving basic abilities such as",
      "vitality and instantaneous force",
      "drastically. She became the",
      "foundation for the various chimeric",
      "monsters that were made after her.",
      "Since she was technologically simple,",
      "she is also able to be mass-produced,",
      "of which several Chimera Slugs have",
      "been in the Angelic Dominion. They",
      "are deployed as defensive forces in",
      "important facilities away from the",
      "eyes of the Goddess' people, such as",
      "laboratories.",
      "",
      "However, she has the flaw of being",
      "energy-inefficient, and requires",
      "large quantities of semen to survive.",
      "By using her two semen-extracting",
      "tentacles, she'll often squeeze",
      "the semen out of multiple men until",
      "their life runs out. Fortunately for",
      "the Chimera Slugs, there is no",
      "shortage of men in the Dominion who",
      "either disobey Ilias' teachings, have",
      "rebellious tendencies, or simply",
      "can't work any more, so it seems they",
      "won't have to starve for the time",
      "being.",
      "",
      "Artist: Setouchi",
    ],
    587 => [
      "A plant-type chimeric monster created",
      "from Promestein's research. She was",
      "created by manifesting plant organs",
      "in parts of the female body that were",
      "similar in nature. Her plant parts",
      "have strong regenerative abilities",
      "and can grow back in the blink of an",
      "eye if sliced off. Additionally, due",
      "to her disposition to attack anyone",
      "who intrudes upon her territory, it",
      "seems a few of them have been mass-",
      "produced at the Angelic Dominion's",
      "research lab as defensive forces for",
      "key locations.",
      "",
      "Displaying no intelligence at all,",
      "she simply attacks prey to quench her",
      "thirst. She preys indiscriminately",
      "upon humans regardless of their",
      "gender and sometimes even monsters,",
      "but she is particularly ruthless when",
      "attacking human men. The lewd flowers",
      "and vines growing on her body are",
      "designed to suck up semen, wrapping",
      "around a man's genitals and forcing",
      "ejaculations to squeeze out every",
      "last drop of it. After squeezing out",
      "all of his semen, the plant parts",
      "wrap all around her prey's body to",
      "swallow him whole.",
      "",
      "Artist: Delphinus",
    ],
    588 => [
      "A berserker formed from holy mana in",
      "the atmosphere reacting with the",
      "lingering resentments of Heinrich,",
      "who was sealed in the Sealed Sinner's",
      "Prison. It barely has any will of its",
      "own, driven solely by his hatred",
      "towards angels. So long as Heinrich's",
      "soul remains, they will continue to",
      "materialize endlessly, and will never",
      "truly disappear no matter how many",
      "times they are defeated. They are",
      "entities that wield extraordinary",
      "power solely for the slaughtering of",
      "angels.",
      "",
      "In addition to being drawn towards",
      "highly spiritual locations like the",
      "Forest of Spirits, they also react",
      "towards beings who are closely",
      "related to, though the details behind",
      "this behavioral logic are shrouded in",
      "mystery.",
      "",
      "Artist: Setouchi",
    ],
    589 => [
      "A chimeric monster created from",
      "Promestein's research. She was an",
      "attempt to recreate the ancient",
      "biological weapon Giganto Weapon, but",
      "her power fell far short of those",
      "expectations. Considering that, she",
      "still undoubtedly boasts combat",
      "capabilities surpassing those of",
      "ordinary monsters, and a few of them",
      "have been manufactured to guard",
      "important sites.",
      "",
      "Maintaining her huge body requires an",
      "immense amount of energy, so she",
      "devours any and all humans,",
      "regardless of gender. Of course, it",
      "goes without saying that the semen of",
      "human males is here favorite food.",
      "She also happens to possess",
      "petrification abilities, making her",
      "an extremely dangerous monster.",
      "",
      "Artist: Setouchi",
    ],
    590 => [
      "A chimeric monster created from",
      "Promestein's research. Although she",
      "was an attempt to recreate the",
      "ancient biological weapon Giganto",
      "Weapon, its power was still far",
      "beyond her reach. As a result, it was",
      "decided that the mass-production of",
      "versatile biological weapons was",
      "superior to creating a single",
      "ultimate combat weapon in terms of",
      "both combat and cost-effectiveness.",
      "Along with the decision to mass-",
      "produce Chimera Beasts, the",
      "simplified mass-production model of",
      "that biological weapon, the plans to",
      "recreate the Giganto Weapon came to",
      "an end.",
      "",
      "Although the plans came to a sudden",
      "halt, Typhon still possesses great",
      "combat capabilities, and a few of",
      "them have been created and deployed",
      "at key facilities such as research",
      "labs. It seems they require an",
      "immense amount of energy to maintain",
      "their huge bodies, and many humans",
      "have apparently been sacrificed to",
      "them as food.",
      "",
      "Artist: Setouchi",
    ],
    591 => [
      "One of the Next Dolls, the strongest",
      "chimeric monsters created by",
      "Promestein. Built to fight against",
      "Erubetie of the Monster Lord's Four",
      "Heavenly Knights, her body is",
      "equipped with various special",
      "armaments to counteract her unique",
      "abilities. Her wide array of anti-",
      "slime equipment includes super-",
      "vibration blades capable of easily",
      "cutting through slime bodies at a",
      "molecular level, vibration armor that",
      "destroys any slime tissue clinging to",
      "her own body, and a plasma field",
      "generator that uses microwaves to",
      "heat a wide area and cause",
      "evaporation. She also possesses",
      "high basic combat capabilities, and",
      "her primary weapon, the super-",
      "vibration blade, is tremendously",
      "effective against physical armor.",
      "",
      "As a result of being equipped with",
      "these various mechanical devices",
      "however, she is vulnerable to shocks",
      "and impacts during melee combat. In",
      "addition, operating these various",
      "armaments consumes an immense amount",
      "of power, making her unsuited for",
      "prolonged battles. While there is no",
      "denying that she lacks versatility",
      "and is overspecialized towards",
      "countering Erubetie, these flaws",
      "won't become apparent before the",
      "fight is over unless she is up",
      "against a strong opponent at the same",
      "level as her.",
      "",
      "Artist: Thomas",
    ],
    592 => [
      "A fully autonomous machine created",
      "by Promestein. Her body is entirely",
      "mechanical with no biological organs",
      "used at all, making her completely",
      "mechanical lifeform. With the",
      "completion of Laplace's development,",
      "Promestein had concluded that the",
      "Roid-type had now been perfected.",
      "",
      "After the Alliance of Wisdom had",
      "formed a pact with the Angelic",
      "Dominion, Laplace was sent over to",
      "the Dominion. She was invited to the",
      "Remina labs to support their",
      "research, but she has also been",
      "called upon in times of emergency for",
      "her fighting capabilities. Her",
      "processing power has achieved a",
      "theoretical maximum value, and she",
      "is able to operate multiple",
      "extraction machines simultaneously.",
      "This capability is also very",
      "outstanding in combat. Enemies who",
      "face her will be mercilessly beaten",
      "down and made into experimental.",
      "samples at the labs.",
      "",
      "Artist: xelvy",
    ],
    593 => [
      "Trap stone statues that have been",
      "placed at important locations in the",
      "Angelic Dominion. When human men",
      "approach these restricted areas,",
      "they release an aphrodisiac gas that",
      "clouds their minds. Then, once a man",
      "inserts into the genitals on her",
      "crotch, her petrification magic will",
      "activate, turning his body into part",
      "of the statue. Additionally, with",
      "the second Great Monster Wars in",
      "sight, they have been given the",
      "ability to patrol specific routes.",
      "They are stationed in multiple key",
      "locations as reserve forces that",
      "perform semi-automatic defense.",
      "",
      "Men who became petrified while",
      "having intercourse with the stone",
      "statue remain there as a warning to",
      "others. However, this has ended up",
      "arousing the sexual desires of some",
      "men, and there seems to be no",
      "shortage of them who are willing to",
      "throw themselves at the Themis",
      "Traps. Especially around some work",
      "sites, due to many instances of",
      "second-class citizens worn-out from",
      "working throwing themselves at",
      "Themis Traps, measures have been",
      "taken to remove them from these",
      "areas.",
      "",
      "Artist: frfr",
    ],
    594 => [
      "One of the Next Dolls, the strongest",
      "chimeric monsters created by",
      "Promestein. Built to fight against",
      "Tamamo of the Monster Lord's Four",
      "Heavenly Knights, she was created",
      "using body tissue collected from her",
      "tail fur. She is essentially a clone",
      "type that has undergone biological",
      "and mechanical modifications to the",
      "point where she is unrecognizable",
      "from the original.",
      "",
      "In order to withstand the superhuman",
      "strength of the earth that Tamamo",
      "wields, her body was designed with an",
      "emphasis on improving defensive",
      "ability. Additionally, anti-magic",
      "talismans were woven into her entire",
      "body to nullify a wide array of",
      "spells. Through the incorporation of",
      "Tamamo's cellular tissue, she is also",
      "able to use a variety of magical arts",
      "such as Taoism. She is even capable",
      "of wielding the earth's power, and",
      "has overall high combat abilities.",
      "Because of her heavy armor however,",
      "her speed performance is slightly",
      "inferior compared to the other Next",
      "Dolls, though isn't a very",
      "significant flaw.",
      "",
      "Artist: Thomas",
    ],
    595 => [
      "Angels belonging to the ninth circle",
      "in the angel hierarchy (Angels), they",
      "were created as brain work",
      "specialists to perform research and",
      "development. They possesses extremely",
      "high intelligence compared to other",
      "angels, but are skeptical of the",
      "Goddess' absolute rule because of",
      "this and is not especially loyal to",
      "her. With that said, most Furiels",
      "would have nowhere to go without",
      "research jobs, so they just do as",
      "they're told by their superiors and",
      "work on cutting-edge science.",
      "",
      "Being that their original purpose was",
      "brain work, they weren't expected to",
      "have fighting capabilities, but",
      "thanks to their excellent logical",
      "processing capabilities, they have",
      "devised their own unique techniques",
      "in addition to the usual wielding of",
      "holy mana. Their attack performance",
      "is incredibly high thanks to these",
      "techniques, which utilize their",
      "knowledge of physics and chemistry.",
      "Additionally, their bodies were",
      "strengthened to withstand long",
      "periods of working, resulting in them",
      "having unexpectedly high combat",
      "capabilities. While they are not",
      "belligerent in any way, they can be",
      "called upon as a fighting force in",
      "case of an emergency.",
      "",
      "Artist: Silk",
    ],
    596 => [
      "A semen-extracting plant developed",
      "for the purpose of endlessly drawing",
      "semen out of a male human imprisoned",
      "within her while keeping them alive.",
      "They are a kind of chimeric monster",
      "that was mass-produced based on an",
      "enlarged womb type that was",
      "accidentally created in an angel",
      "hybrid experiment. Possessing wills",
      "of their own and high intelligence,",
      "the Plants maintain the samples",
      "within them. Sometimes a sample may",
      "attempt to escape, only to be",
      "captured by a Plant and taken back",
      "inside.",
      "",
      "Additionally, the plant part of this",
      "chimera is the womb, and the man",
      "immersed inside it is kept alive like",
      "a baby inside a mother. In that",
      "state, he is made to ejaculate",
      "repeatedly so that his semen can be",
      "harvested. Once submerged inside the",
      "Plant, most men will become so",
      "immersed in sweet ecstasy that they'll",
      "become completely crippled, existing",
      "only to be drained from. The Drain",
      "Plants are also used for reproductive",
      "experiments, facilitating efficient",
      "fertilization by sending egg cells",
      "through their suction tube.",
      "",
      "Artist: Delphinus",
    ],
    597 => [
      "A roid-type chimeric monster created",
      "by Promestein. Developed to",
      "efficiently harvest semen from",
      "multiple partners, she is capable of",
      "operating 48 semen-extracting units",
      "installed all throughout her body",
      "simultaneously. When the Recreation",
      "Plan was initiated, in preparation",
      "for the arrival of prisoners from",
      "around the world, the Drainroid's",
      "purpose was to extract semen from",
      "large numbers of men in an assembly",
      "line fashion. Even after the chaos",
      "crisis caused the Recreation Plan to",
      "fall through, a small number were",
      "still being mass-produced for semen",
      "harvesting.",
      "",
      "Her mechanization rate is incredibly",
      "high, with only some central organs",
      "like the brain and spinal column not",
      "being replaced with machines. While",
      "not designed for battle, the",
      "Drainroid has strong physical",
      "abilities that, combined with the",
      "high performance of all of her body's",
      "extraction units, give her high",
      "combat capabilities. Once she",
      "switches into self-defense mode,",
      "even a yoma-class monster would have",
      "difficulty fighting against her.",
      "",
      "Artist: xelvy",
    ],
    598 => [
      "A type of Drainroid developed by the",
      "Alliance of Wisdom that was easily",
      "mass-produced using technology",
      "unique to the Angelic Dominion. She",
      "has diminished performance compared",
      "to the Drainroid, but the excessive",
      "production costs have been",
      "drastically reduced. As a result,",
      "mass-producing them achieves better",
      "semen-harvesting efficiency compared",
      "to Drainroids. There also appears to",
      "have been future plans to deploy",
      "them in second-class citizen",
      "settlements for purposes such as",
      "semen harvesting, worker disposal,",
      "or for rewards.",
      "",
      "She is able to milk semen from",
      "twelve men simultaneously, and her",
      "operating costs are very low. She",
      "also has functions to forcibly",
      "immobilize violent targets, making it",
      "possible to put her to use in combat.",
      "Her self-defense armaments are also",
      "powerful, and a program that allows",
      "her to respond to attacks on the lab",
      "has been installed into her. A hell",
      "of merciless semen milking will no",
      "doubt await any intruders captured by",
      "a Handyroid.",
      "",
      "Artist: xelvy",
    ],
    599 => [
      "One of the Seven Archangels",
      "created by the Goddess Ilias from",
      "the Angelic Dominion during the",
      "Great Monster Wars and designed as",
      "the eldest of the Twin Angels with",
      "nuclear fusion reactors embedded",
      "within their bodies. They boast",
      "boundless energy reserves,",
      "allowing them to unleash",
      "devastating attacks rapidly. Their",
      "signature move, Atomic Heaven,",
      "performed by directly linking",
      "reactors with her little sister,",
      "Sandalphone, rivals even the Sword",
      "of the Heavens of Micaela, which",
      "was considered the strongest",
      "attack in the Dominion, and they",
      "can even fire it consecutively.",
      "However, despite their seemingly",
      "infinite energy, prolonged",
      "high-output operations cause their",
      "reactors to overheat,",
      "necessitating cooling periods.",
      "Still, they are undoubtedly",
      "unparalleled in raw firepower",
      "among the Seven Archangels, so",
      "while this may appear to be a",
      "weakness, only an opponent of",
      "significantly higher power could",
      "exploit such a vulnerability",
      "before they recover.",
      "",
      "Regular maintenance requirements",
      "tether her and her sister to the",
      "Remina Research Facility, where",
      "they also oversee its management.",
      "Though equipped with advanced",
      "technical knowledge due to this",
      "role, Metatronne finds such duties",
      "irksome and unsuited to her",
      "nature. Her fiery and confident",
      "personality contrasts sharply with",
      "Sandalphone's reserved and timid",
      "demeanor. Deeply protective of her",
      "sister, Metatronne will readily",
      "endure personal loss or discomfort",
      "for Sandalphone's sake, a",
      "testament to their unshakable",
      "bond.",
      "",
      "Artist: xelvy",
    ],
    600 => [
      "One of the Seven Archangels",
      "created by the Goddess Ilias from",
      "the Angelic Dominion during the",
      "Great Monster Wars and designed as",
      "the youngest of the Twin Angels",
      "with nuclear fusion reactors",
      "embedded within their bodies. They",
      "boast boundless energy reserves,",
      "allowing them to unleash",
      "devastating attacks rapidly. Their",
      "signature move, Atomic Heaven,",
      "performed by directly linking",
      "reactors with her big sister,",
      "Metatronne, rivals even the Sword",
      "of the Heavens of Micaela, which",
      "was considered the strongest",
      "attack in the Dominion, and they",
      "can even fire it consecutively.",
      "However, despite their seemingly",
      "infinite energy, prolonged",
      "high-output operations cause their",
      "reactors to overheat,",
      "necessitating cooling periods.",
      "Still, they are undoubtedly",
      "unparalleled in raw firepower",
      "among the Seven Archangels, so",
      "while this may appear to be a",
      "weakness, only an opponent of",
      "significantly higher power could",
      "exploit such a vulnerability",
      "before they recover.",
      "",
      "Regular maintenance requirements",
      "tether her and her sister to the",
      "Remina Research Facility, where",
      "she also oversees its management.",
      "Though equipped with advanced",
      "technical knowledge due to this",
      "role, Sandalphone finds such",
      "duties irksome and unsuited to her",
      "nature. Reserved and timid by",
      "nature, she places absolute trust",
      "in her older sister. Her status as",
      "a created being fosters a deep",
      "compassion for experimental",
      "subjects and others like her.",
      "",
      "Artist: xelvy",
    ],
    601 => [
      "Angels belonging to the ninth circle",
      "in the angel hierarchy (Angels), they",
      "are non-combatants who perform",
      "domestic chores such as cleaning and",
      "laundry. That's what their original",
      "purpose was, but because Ilias liked",
      "how they looked, she gave them powers",
      "far beyond what they needed for that.",
      "Their abilities have been greatly",
      "enhanced all around, resulting in",
      "them being stronger than combat-",
      "specialized angels.",
      "",
      "They are calm and devoted, but they",
      "absolutely hate being interrupted",
      "during their everyday routine, and",
      "will mercilessly punish trespassers.",
      "In particular, her service utilizing",
      "her ample breasts will give men",
      "heavenly pleasure at first, which",
      "then turns into a pleasure hell as",
      "she keeps going on and on.",
      "",
      "Artist: Arekishi",
    ],
    602 => [
      "Angels belonging to the ninth circle",
      "in the angel hierarchy (Angels), they",
      "are non-combatants who handle cooking",
      "duties. That's what their original",
      "purpose was, but because Ilias liked",
      "how they looked, she gave them powers",
      "far beyond what they needed for that.",
      "Their abilities have been greatly",
      "enhanced all around, resulting in",
      "them being stronger than combat-",
      "specialized angels.",
      "Traditionally, angels have had",
      "virtually no need for meals and thus",
      "the concept of food was inevitably",
      "looked down upon. However, as part of",
      "a national power strengthening plan",
      "established by the Goddess Ilias, a",
      "goal of promoting physical and mental",
      "fitness through food had emerged. In",
      "accordance with that, angels",
      "specialized in food were created",
      "shortly after. As a result, there",
      "has been a gradual increase in the",
      "number of angels interested in food.",
      "",
      "They are dedicated professionals who",
      "only think about cooking, and are",
      "constantly researching new dishes and",
      "ingredients. However, they express",
      "incredible fury towards those who",
      "belittle their cooking or get in the",
      "way of their work, and attack them",
      "with their frying pans. Careless men",
      "that they've beaten up are subjected",
      "to pleasure torture using their",
      "breasts, which are so plump that they",
      "get in the way of their cooking.",
      "",
      "Artist: Arekishi",
    ],
    603 => [
      "Small angels belonging to the eighth",
      "circle in the angel hierarchy",
      "(Archangels). Originally created to",
      "be messengers for important tasks,",
      "their adorable appearance pleased the",
      "Goddess Ilias, and so she bestowed",
      "them powers that were clearly",
      "excessive for their messenger duties.",
      "Their powers now surpass even those",
      "of mid-ranked angels despite their",
      "low ranking, and their combat prowess",
      "is several levels above angels",
      "specialized for battle.",
      "Due to their very likable appearance,",
      "they're often assigned to work",
      "directly alongside the Chosen Ones.",
      "As a result, they've become the most",
      "beloved angels of all in the Angelic",
      "Dominion. On the contrary, angels",
      "with bizarre appearances who aren't",
      "permitted to appear before the Chosen",
      "Ones seem to loathe them as being",
      "blatantly favored.",
      "",
      "They're very earnest and faithfully",
      "carry out the duties they're tasked",
      "with. They're also very hard-working",
      "and appear to spend their free time",
      "studying. When they punish sinners,",
      "they use their ample breasts to",
      "slowly tease them.",
      "",
      "Artist: Arekishi",
    ],
    604 => [
      "A chimeric monster created by",
      "Promestein, she is a type known as a",
      "\"roid\" that was made using many",
      "biomechanical parts. Using a lamia",
      "as a base, she has undergone various",
      "modifications and has been endowed",
      "with excellent physical abilities.",
      "",
      "Forty-eight extraction devices have",
      "been built into her body to test the",
      "degree to which mechanical organs can",
      "be controlled by a living organism's",
      "brain. However, she doesn't fully",
      "understand how most of them are used,",
      "and mainly sticks to using up to five",
      "types of them regularly. Naturally,",
      "their effectiveness is tremendous,",
      "and she's able to extract semen from",
      "multiple men at once.",
      "",
      "Although she was a trial model, she",
      "was reassigned to combat duty and",
      "dispatched to the Angelic Dominion as",
      "an expeditionary unit after basic",
      "data had been acquired. While they",
      "had been deployed to attack rebel",
      "organizations and suppress uprisings,",
      "most of their actions were tactically",
      "meaningless, and didn't contribute",
      "much to the fighting.",
      "",
      "Artist: xelvy",
    ],
    605 => [
      "A high-ranking angel prototype",
      "created after the Great Monster Wars,",
      "she was developed as a trial run in",
      "anticipation of a mass production of",
      "mechanical angels. Although her",
      "exterior had been damaged, it was",
      "quickly restored with techno-",
      "organic system. While her offensive",
      "and defensive abilities increased",
      "based on the situation, her agility",
      "decreases due to the heavier armor.",
      "Her energy consumption has also",
      "skyrocketed, making this more like",
      "a runaway form as opposed to an",
      "enhancement.",
      "",
      "Artist: UN_DO",
    ],
    606 => [
      "A high-ranking angel prototype",
      "created after the Great Monster Wars,",
      "she was developed as a trial run in",
      "anticipation of a mass production of",
      "mechanical angels. Her techno-organic",
      "system has overreacted to repeated",
      "damage and her mechanical cells are",
      "now invading her entire body, causing",
      "excessive output and armorization.",
      "The strain this inflicts upon her",
      "body however is extraordinary, and",
      "she no longer appears to be unable to",
      "fully maintain her reason.",
      "",
      "Artist: UN_DO",
    ],
    607 => [
      "A high-ranking angel prototype",
      "created after the Great Monster Wars,",
      "she was developed as a trial run in",
      "anticipation of a mass production of",
      "mechanical angels. The damage she's",
      "sustained has exceeded acceptable",
      "levels, causing her techno-organic",
      "system to go out of control. Her",
      "entire body has been reconstructed as",
      "a weapon, giving her extraordinary",
      "firepower and fortress-like defenses.",
      "In exchange for that, her body has",
      "already started to break down, and",
      "her self-destruction will be",
      "inevitable after functioning for a",
      "short while.",
      "",
      "Artist: UN_DO",
    ],
    608 => [
      "The Goddess of Creation who had",
      "fallen to the surface world. Despite",
      "having been drastically weakened,",
      "she fought many battles while",
      "roaming the surface, regaining power",
      "equivalent to a high-ranking angel.",
      "In cooperation with the Ilias of the",
      "Angelic Dominion, she currently",
      "leads the three Seraphim in",
      "occupying the Monster Lord's Castle",
      "in the Singularity World. The Slime",
      "Girl and Dog Girl who are always at",
      "her side appear to have been her",
      "companions since the start of her",
      "adventure.",
      "",
      "Artist: Akazawa RED",
    ],
    609 => [
      "A Slime Girl who accompanies the",
      "Goddess Ilias. She deeply admires",
      "Ilias and has gained considerable",
      "combat experience herself during",
      "their long journey. She appears to",
      "have learned support skills such as",
      "dancing and singing to assist Ilias,",
      "but she still isn't reliable enough",
      "to fight on the front lines.",
      "",
      "Artist: Kenkō Cross",
    ],
    610 => [
      "A Dog Girl who accompanies the",
      "Goddess Ilias. She deeply admires",
      "Ilias and has gained considerable",
      "combat experience herself during",
      "their long journey. She appears to",
      "have learned support skills such as",
      "recovery skills and strengthening",
      "white magic to assist Ilias, but she",
      "still isn't reliable enough to fight",
      "on the front lines.",
      "",
      "Artist: Uminoyama",
    ],
    611 => [
      "An angel belonging to the fourth",
      "circle of the nine in the angel",
      "hierarchy (Dominion). She descends",
      "when heroes and saints who had",
      "dedicated their lives to the Goddess",
      "die to grant them pleasure as",
      "reward while ascending their souls to",
      "Heaven, which is her main duty.",
      "Although she is ridiculed as the",
      "\"Angel Whore\" for her position, she",
      "appears to take this moniker",
      "positively.",
      "",
      "Due to her position, her sexual",
      "techniques are said to be the best",
      "in Heaven, and even the most stubborn",
      "of souls will go crazy with pleasure",
      "from her skills. Sometimes the souls",
      "become so addicted to the pleasure",
      "that it cripples them, which impedes",
      "their transmigration. Additionally,",
      "she's mastered skills for pleasing",
      "women as well, since the souls of",
      "saints and heroes aren't exclusively",
      "men.",
      "",
      "Originally, it was the duty of the",
      "Valkyries to guide the souls of",
      "heroes who had devoted themselves to",
      "the Goddess to Heaven. However, the",
      "serious and straight-laced Valkyries",
      "were unpopular for performing their",
      "duties in an overly businesslike and",
      "unfriendly manner, and this new",
      "position appears to have been",
      "established several hundred years",
      "ago.",
      "",
      "Artist: Delphinus",
    ],
    612 => [
      "An angel belonging to the second",
      "circle of the nine in the angel",
      "hierarchy (Cherubim). After the",
      "Whiteyels' combat abilities had been",
      "drastically enhanced as a result of",
      "receiving Ilias' favor, similar",
      "angels had begun to be created as",
      "combat types. Holmiel was created as",
      "a result of this, a humanoid angel",
      "without a deformed body, but endowed",
      "with the highest levels of combat",
      "prowess in the Angelic Dominion.",
      "She excels in hand-to-hand combat and",
      "possess great control over holy",
      "energy. She also has great leadership",
      "skills, making her a reassuring",
      "presence as a pure combat type. Many",
      "of them comprise the Goddess' elite",
      "guard at the Ilias Temple, and some",
      "have been selected to serve as",
      "division commanders.",
      "",
      "Holmiels have fierce and competitive",
      "personalities compared to the calm",
      "and earnest Whiteyels. They will",
      "utterly beat down the Goddess'",
      "enemies and inflict merciless",
      "punishment upon them.",
      "",
      "Artist: Arekishi",
    ],
    613 => [
      "A next-generation human developed to",
      "replace humanity following the re-",
      "creation. The Goddess Ilias",
      "enumerated the undesirable traits of",
      "current humans, and as a result of",
      "Promestein incorporating these as",
      "points to improve upon in her plans,",
      "they have taken on this form. Despite",
      "their strange appearance, their DNA",
      "is unmistakably human. Their physical",
      "abilities and intelligence are far",
      "superior to current humans, and all",
      "of their organs are logically",
      "designed. They are capable of",
      "surviving on water alone, and don't",
      "require oxygen to breathe.",
      "",
      "Reproduction is done by predating",
      "upon males using their female",
      "genitals. By assimilating the male,",
      "they acquire new genes, and he is",
      "effectively reborn. Males devoured",
      "like this experience a lifetime of",
      "pleasure before their lives end and",
      "are offered to the next generation.",
      "",
      "Artist: frfr",
    ],
    614 => [
      "A clone of the hero Luka, created",
      "through Promestein's genetic",
      "engineering technology. She was",
      "originally made to change her sex at",
      "will, but when the Angelic Dominion",
      "started mass-producing them using",
      "data they were provided with, their",
      "sex became fixed as female. While",
      "Luka's ability to interact with",
      "other dimensions was expected to be",
      "useful, theirs were nowhere near as",
      "potent as the original's. Thus mass-",
      "production was carried out in order",
      "to approach the original's power by",
      "utilizing multiple brains in tandem,",
      "but part of their laboratory was",
      "destroyed by Lucifina's attack.",
      "All of the Doppels that existed at",
      "that time were taken with her to the",
      "moon.",
      "",
      "Artist: frfr",
    ],
    615 => [
      "A female warrior who appears to be",
      "an officer-ranked member of the",
      "Moon-Dwellers. While she has the",
      "same face as all of the other",
      "individuals, her hairstyle and",
      "armaments are different, implying",
      "that she is of a higher rank than",
      "the average soldier. Her combat",
      "abilities are also remarkably",
      "superior compared to average",
      "soldiers, possessing such power that",
      "even mid-ranking angels are no match",
      "for her. She also has such excellent",
      "judgement and tactical insight that",
      "despite having conducted repeated",
      "raids, not a single one of the Moon-",
      "Dwellers has ever been captured.",
      "",
      "This individual, known as Luka Kyrie,",
      "bears similar characteristics to a",
      "valkyrie and boasts exceptional spear",
      "skills. Among the four officer-ranked",
      "members, she's said to be the most",
      "calm and collected among them, with",
      "field reports indicating she's a very",
      "formidable opponent.",
      "",
      "Artist: frfr",
    ],
    616 => [
      "A chimeric monster created through",
      "Promestein's genetic engineering",
      "technology. Created as a capture-",
      "model prototype, her existence",
      "received almost no attention from",
      "the Alliance of Wisdom, but when",
      "designs for various chimeric monsters",
      "were delivered to their allies in the",
      "Angelic Dominion, they decided to",
      "mass-produce them immediately. Mass-",
      "production started at their lab",
      "in the Dominion, and many of them",
      "were dispatched to various frontiers",
      "around the world. Due to second-class",
      "citizens often running away due to",
      "harsh working conditions, this",
      "chimera type that automatically",
      "captures targets is considered very",
      "useful.",
      "",
      "However, there have also been many",
      "instances of Chimera Prisons escaping",
      "themselves, weary of constant escapee",
      "capture missions. Several of them",
      "have gone feral, and now pose",
      "problems for society. As a result of",
      "these incidents, the one responsible",
      "for signing the mass-production plan",
      "for Chimera Prisons was demoted to",
      "worker, and after being sent off to",
      "the frontier, has gone missing after",
      "running away.",
      "",
      "Artist: Setouchi",
    ],
    617 => [
      "An artificial spirit created through",
      "machine technology that has the power",
      "to control wind. She is stationed at",
      "the Forest of Spirits in the Natalia",
      "region ruled by Gabriela, and is",
      "responsible for the movement of wind.",
      "Her power is comparable to Sylph's,",
      "but she requires an enormous amount",
      "of life energy to maintain.",
      "Consequently, many male second-class",
      "citizens and political prisoners are",
      "taken to the Forest of Spirits to",
      "replenish her energy through sexual",
      "intercourse. This fact is considered",
      "to be one of the Angelic Dominion's",
      "top secrets.",
      "",
      "While she isn't cruel, she is",
      "incredibly greedy and will often",
      "squeeze the semen out of the men",
      "offered to her until they are",
      "completely drained. She appears to be",
      "dissatisfied with being managed and",
      "unable to leave the forest, and",
      "yearns to be free to sweep across the",
      "outside world.",
      "",
      "Artist: UN_DO",
    ],
    618 => [
      "An anomaly born among the fairy",
      "race, she possesses powers over",
      "nature that are said to rival the",
      "Four Spirits, and is even able to",
      "freely control the weather and",
      "climate. Free-spirited and",
      "uninhibited, she left her home of",
      "Fairy's Island to go wandering",
      "around on a journey, causing trouble",
      "wherever she went. It should be",
      "noted that most Chosen Ones in the",
      "Angelic Dominion misunderstand",
      "fairies to be young angels. But when",
      "a crisis arises in her homeland, she",
      "also displays a very proactive side",
      "of herself.",
      "",
      "She is mischievous not unlike most",
      "fairies and will sometimes stalk",
      "humans that catch her eye. She has",
      "also been confirmed to have engaged",
      "in malicious acts such as repeatedly",
      "committing sexual pranks, particularly",
      "towards timid men she sees.",
      "",
      "Artist: UN_DO",
    ],
    619 => [
      "A monster hiding in the forest that",
      "has undergone a mutation. The cause",
      "of this mutation appears to be chaos",
      "erosion, but the specific have yet",
      "to be confirmed. They appear to have",
      "originally been just mushroom girls,",
      "but they've lost their reason and",
      "their proliferation rate increased",
      "drastically. Their physical abilities",
      "and the toxicity of their spores have",
      "also greatly increased, making them",
      "extremely dangerous beings. The",
      "angels have been persistently",
      "carrying out extermination,",
      "operations, completely eradicating",
      "them in forests near residential",
      "areas. However, the Fairy's Forest is",
      "extremely vast, so total eradication",
      "has been deemed impossible, and a",
      "containment strategy is being",
      "adopted.",
      "",
      "They use living organisms as seedbeds",
      "for their explosive growth. Their",
      "victims have their energy sucked dry",
      "and shrivel up in an instant. If",
      "their seedbed is a male, several of",
      "them will cluster around his crotch",
      "to squeeze out his sperm. He will",
      "then wither away completely while",
      "immersed in ecstasy.",
      "",
      "Artist: frfr",
    ],
    620 => [
      "Myconids that were believed to have",
      "gathered together into a single",
      "collective entity with some degree of",
      "intelligence, but the specifics have",
      "yet to be confirmed. The female forms",
      "overflowing from the main body can",
      "change their shape and have varying",
      "degrees of intelligence, with some",
      "possessing enough to be able to hold",
      "a normal conversation. The reason why",
      "they are able to use time magic is a",
      "mystery, but they undoubtedly have a",
      "slight ability to interfere with",
      "space-time. While they are incredibly",
      "greedy, they never appear to leave",
      "their forest territory. The cost of",
      "exterminating Myconids of this level",
      "isn't worth it, so the angel soldiers",
      "haven't gotten involved and have",
      "instead enforced a strict isolation",
      "of Fairy's Island.",
      "",
      "They'll attack any living creature",
      "regardless of species and gender,",
      "greedily absorbing them into their",
      "body. During that moment, their",
      "spores cause their victim to fall",
      "into a trance, causing them to",
      "repeatedly climax from the supreme",
      "pleasure as they become one with the",
      "Matango. Should their prey be a male,",
      "he will end up releasing all of his",
      "semen into them.",
      "",
      "Artist: Setouchi",
    ],
    621 => [
      "A monster hiding in the forest that",
      "has undergone a mutation. The cause",
      "of this mutation appears to be chaos",
      "erosion, but the specific have yet",
      "to be confirmed. Some of their DNA",
      "appears to match the Little Bug's",
      "and Chimera Bug's, leading to",
      "speculation that some of their cells",
      "may have leaked into the",
      "environment. Their characteristics",
      "are no different from typical insect",
      "monsters, but they have greatly",
      "improved physical abilities. Their",
      "vitality has drastically increased,",
      "and they demonstrate fighting",
      "capabilities that make them",
      "difficult for angel soldiers to",
      "exterminate.",
      "",
      "They attack anyone who intrudes upon",
      "their territory, and should the",
      "intruder be a man, he will be forced",
      "to mate with them. Fortunately,",
      "their reproductive capabilities",
      "aren't high for insect-type",
      "monsters, so they don't explosively",
      "procreate.",
      "",
      "Artist: frfr",
    ],
    622 => [
      "A monster hiding in the forest that",
      "has undergone a mutation. The cause",
      "of this mutation appears to be chaos",
      "erosion, but the specific have yet",
      "to be confirmed. Although they are",
      "plant-based, some of their DNA",
      "appears to match the Chimera",
      "Tongue's, leading to speculation",
      "that some of their cells may have",
      "leaked into the environment. They",
      "have tongue-like organs all over",
      "their bodies that they can extend",
      "and shrink freely, as well as taste",
      "with. They're said to sometimes",
      "capture living creatures by wrapping",
      "them in their tongues and licking",
      "them thoroughly to enjoy their",
      "taste.",
      "",
      "Should they catch a male, regardless",
      "of his species, they will thoroughly",
      "lick his genitals. Humans in",
      "particular are prey they rarely get",
      "to capture, and he will likely have",
      "his genitals licked for three days",
      "and three nights. The man will",
      "simply die from exhaustion in most",
      "cases, so caution is necessary",
      "around them.",
      "",
      "Artist: Setouchi",
    ],
    623 => [
      "A plant-type chimeric monster created",
      "from Promestein's research. She was",
      "created by manifesting carnivorous",
      "plant organs in parts of the female",
      "body that were similar in nature. It",
      "seems the human's will has",
      "disappeared after being taken over by",
      "parasitic plants. She was made at the",
      "same time as the Chimera Dryad, but",
      "this one turned out to be extremely",
      "violent, and thus no plans were made",
      "to produce more. However, there are",
      "records of a few test subjects",
      "escaping from the laboratory and",
      "fleeing into Fairy's Island through",
      "the gate (The ones responsible for",
      "this became food for the chimeric",
      "monsters).",
      "",
      "Driven solely by appetite, they seek",
      "out living creatures and devour them",
      "one after another using their",
      "carnivorous plants. They prey upon",
      "humans and angels alike, and should",
      "they catch a man, they will extract",
      "his semen for nourishment before",
      "devouring him. Once they catch",
      "someone, there is no escape for them.",
      "After one uses her various plant",
      "organs to squeeze a man's dry of his",
      "semen, a cruel fate of being",
      "dissolved by her carnivorous plants",
      "awaits him.",
      "",
      "Artist: Delphinus",
    ],
    624 => [
      "The Planet Guardian Butterfly, who",
      "has been slumbering within the",
      "innermost depths of Fairy's Island.",
      "Her existence is akin to the spirit",
      "of the planet itself, concealing the",
      "great energies of the world within",
      "her. Because her influence upon the",
      "planet is so immense, not even the",
      "Goddess Ilias could replace or",
      "eliminate her, so she kept her",
      "contained on Fairy's Island, where",
      "she remains dormant. The fairies and",
      "elves there have come to worship her",
      "as a guardian deity of the planet.",
      "",
      "She's essentially stuck in her pupal",
      "stage and will never fully mature to",
      "soar the skies. She contributes to",
      "the stability of nature and poses no",
      "harm by existing, but if you",
      "carelessly approach her chrysalis,",
      "it will automatically capture you",
      "with its tentacles and suck out your",
      "nutrients. This is not Cosmos' will,",
      "but simply a reflex, as she herself",
      "continues to slumber peacefully.",
      "",
      "Artist: UN_DO",
    ],
    625 => [
      "The Planet Guardian Butterfly Cosmos",
      "that had been dormant on Fairy's",
      "Island, who has now mutated after",
      "absorbing chaos energies. While she",
      "wasn't supposed to fully mature, she",
      "has undergone explosive growth and",
      "emerged from her chrysalis. The",
      "planet's energy hidden within her",
      "has been further strengthened by the",
      "encroachment of chaos, and she has",
      "become an embodiment of destruction",
      "capable of unleashing tremendous",
      "power. Far from being a protector of",
      "the planet any more, she has become",
      "a monstrosity guided by the impulses",
      "of chaos who now seeks destruction.",
      "",
      "Artist: UN_DO",
    ],
    626 => [
      "A Black Alice from another world who",
      "has disguised herself for fun. Having",
      "accepted the Third Goddess Black",
      "Alice's invitation, she has joined",
      "her Black Alice Army, which numbers",
      "over a hundred-thousand. Boasting",
      "magical powers that are renowned as",
      "the strongest among all the Monster",
      "Lords throughout history, they",
      "cause catastrophic damage across",
      "the entire Angelic Dominion.",
      "",
      "Artist: Setouchi",
    ],
