    ],
    648 => [
      "The Eighth Monster Lord who has",
      "become the Third Goddess. Her",
      "inherent tendencies towards causing",
      "devastation have been further",
      "accelerated by her absorption of",
      "chaos. Now she has become a",
      "transcendent being of catastrophe",
      "who enjoys seeing parallel worlds",
      "meet their ends. Able to wield both",
      "holy and dark energy simultaneously,",
      "she possesses unbelievable power",
      "rivalling the other two goddesses.",
      "She is capable of destroying the",
      "world all by herself, making her the",
      "greatest threat that is currently",
      "known to exist.",
      "",
      "Artist: Setouchi",
    ],
    649 => [
      "One of the Next Dolls, the strongest",
      "chimeric monsters created by",
      "Promestein. Built to fight against",
      "Granberia of the Monster Lord's Four",
      "Heavenly Knights, she boasts",
      "overwhelming physical abilities. She",
      "was enhanced at the genetic level with",
      "ultra-fast synaptic nerve conduction,",
      "muscle fiber reinforcement using",
      "nanocarbon fibers, and metabolic",
      "overload through magic. Genetic",
      "engineering, mechanical engineering",
      "and even magic science were all",
      "utilized to strive what could be",
      "considered the ultimate in physical",
      "enhancements.",
      "As a result, all of her combat",
      "capabilities such as strength,",
      "agility, and defense have reached",
      "their theoretical limits. She has no",
      "apparent weaknesses, apart from the",
      "flaw of requiring incredibly high",
      "food intake in order for her to",
      "continue functioning.",
      "",
      "However, this ultimate physical body",
      "also imposes an extremely heavy",
      "biological burden, drastically",
      "shortening her lifespan for which.",
      "she can be maintained. It's believed",
      "that she will live for five years at",
      "most.",
      "",
      "Artist: Thomas",
    ],
    650 => [
      "A strange chimeric monster whose",
      "form resembles a cluster of hair.",
      "This one was created in a manner",
      "similar to spiritualism by exposing",
      "hair cut from young women to high",
      "concentrations of magic and allowing",
      "a deceased woman's soul to possess",
      "it. She was simply part of a project",
      "to explore various ways to create",
      "chimeric monsters, and didn't appear",
      "to have yielded any particularly",
      "useful data.",
      "",
      "Nonetheless, she still provides",
      "excellent fighting power by herself,",
      "and the cluster of hair that is her",
      "body can change shape to make herself",
      "a threat to any foe that faces her.",
      "Once she entangles someone in her",
      "tough hair, it's impossible for them",
      "to escape no matter how strong they",
      "are. She will then suck up their",
      "energy and even absorb their very",
      "body into her.",
      "",
      "While this monster has been given",
      "the name \"Yomotsu-Shikome\", this",
      "was merely a codename used in her",
      "development plan, and she isn't the",
      "same as the Yomotsu-Shikome youkai",
      "that lives in the Yamatai region.",
      "",
      "Artist: frfr",
    ],
    651 => [
      "A mummy type of undead created by",
      "La Croix who serves as a gatekeeper.",
      "Quite different from an ordinary",
      "mummy, her corpse was stolen from the",
      "tomb of Sabasa's first princess, who",
      "bore the most of Sphinx's blood. Her",
      "physical and magical abilities are",
      "beyond the compare of normal mummies",
      "and while her intelligence isn't low",
      "at all, she appears to have sworn",
      "absolute obedience to La Croix.",
      "",
      "Ferme Sara herself was entrusted to",
      "deal with repelled trespassers. If",
      "they are men, she will rape them",
      "without except to replenish her",
      "energy. This former noble's corpse",
      "still retains an alluring pussy that",
      "will immerse men violated by it in a",
      "paradise of pleasure. Her pitiful",
      "prey will be forced to ejaculate",
      "repeatedly without mercy until he",
      "quickly becomes a dried husk.",
      "",
      "Artist: frfr",
    ],
    652 => [
      "Created by La Croix, she is one of",
      "her latest types of zombie made from",
      "the corpse of an angel. Made based on",
      "research data from AD-5, she boasts",
      "an extremely high degree of",
      "perfection. Her physical abilities",
      "and vitality are both high, and",
      "easily surpass those of common",
      "zombies.",
      "However, her mind is unstable and she",
      "constantly feels aroused. In order to",
      "sate her lust and hunger, she attacks",
      "men regardless of how they look. Any",
      "man who becomes her prey will be",
      "violently raped in a manner no",
      "different from murder.",
      "",
      "With La Croix deceased, she now",
      "wanders the laboratory without an",
      "administrator. On the rare occasion",
      "that an intruder shows up, she will",
      "instinctively attack and feast upon",
      "her prey.",
      "",
      "Artist: frfr",
    ],
    653 => [
      "A zombie created by La Croix from the",
      "corpse of a violent dragon that lived",
      "in the Gold region's volcanic zone.",
      "Her physically abilities have",
      "increased drastically compared to",
      "when she was alive, acquiring enough",
      "power to overwhelm even high-ranking",
      "yoma. She is currently stationed as",
      "the gatekeeper of the underground",
      "passage, and devours any prisoners",
      "who try to escape (no humans have",
      "ever made it that far, so she",
      "mainly preys upon monsters)",
      "",
      "She is able to invert her stomach to",
      "bring it outside of her mouth. This",
      "is similar to the ecology of",
      "creatures like frogs and starfish",
      "that wrap prey in their inverted",
      "stomach to consume them. The Dragon",
      "Zombie Girl's inverted stomach takes",
      "the form of a human female to prey",
      "upon unsuspecting men. It works",
      "similarly to an anglerfish lure, and",
      "once someone is caught by it, they",
      "get eaten.",
      "",
      "Artist: UN_DO",
    ],
    654 => [
      "An autonomous android created as the",
      "first model of anti-apoptosis",
      "fighting machines. Built with the",
      "most powerful weapons and advanced",
      "technology around, she has attained",
      "such combat capabilities that she",
      "could be described as the ultimate",
      "mobile weapon. Her personality was",
      "supposed to have been configured to",
      "make her brave and proactive, but she",
      "has a strong tendency to be over-",
      "confident and belligerent. Despite",
      "her personalities flaws, there's no",
      "denying that she's a fighting machine",
      "boasting overwhelming power, and",
      "nevertheless obeys Promestein's",
      "orders without question.",
      "",
      "She was also built with an artificial",
      "vagina capable of simulating sexual",
      "intercourse, and she considers the",
      "fact that human men lust over her as",
      "a sign of her excellence as an",
      "android. Convinced that being able",
      "to engage in simulated sex with human",
      "men is proof of her superiority over",
      "them, she also bears a twisted",
      "sadistic desire to squeeze human",
      "sperm with her mechanical vagina, and",
      "seems to delight in dominating men",
      "with its pleasure.",
      "",
      "Artist: Nuppehofu",
    ],
    655 => [
      "A clone of the hero Luka, created",
      "through Promestein's genetic",
      "engineering technology. She was",
      "originally made to change her gender",
      "at will, but when the Angelic",
      "Dominion started mass-producing them",
      "using data they were provided with,",
      "their gender became fixed as female.",
      "Having been rescued by Lucifina, the",
      "Doppels regard her as their mother",
      "and organized themselves into an",
      "armed force the moon. Oddly enough",
      "however, even these clones have",
      "differences in personality and",
      "ability, with the stronger Doppels",
      "being responsible for defending the",
      "moon's surface as elite guards. These",
      "individuals are known as the Doppel",
      "Elite.",
      "",
      "Artist: frfr",
    ],
    656 => [
      "A gigantic worm resembling an antlion",
      "that appears on the moon's surface.",
      "When the Doppels were migrated to the",
      "moon, they carried microorganisms",
      "with them which underwent explosive",
      "evolution from exposure to mana and",
      "cosmic rays which turned them into",
      "monsters. They aren't space creatures",
      "native to the moon's surface and it's",
      "unclear what they feed upon there,",
      "but it's theorized that some prey",
      "organisms may have also evolved from",
      "similar microbes. They appear to be",
      "a natural enemy of the Doppels, who",
      "defeat them by fighting them in",
      "groups.",
      "",
      "Because they are creatures influenced",
      "by mana, they have acquired a strong",
      "craving for human semen. Because this",
      "bodily fluid doesn't exist on the",
      "moon's surface however, they still",
      "don't know its sweet taste. If one",
      "were to capture a human male, she",
      "would revel in the forbidden taste",
      "and slurp up all of his fluids.",
      "",
      "Aritst: Setouchi",
    ],
    657 => [
      "One of the four among the Doppels who",
      "have exceptional abilities. This one",
      "has a light build with superior",
      "speed, but that's not to say she's",
      "powerless as she also excels with",
      "sword techniques. While she has a",
      "very lighthearted personality, her",
      "flexible thinking comes proves to be",
      "advantageous on the battlefield. In",
      "urban warfare, she excels at tactics",
      "involving encirclement to wipe out",
      "enemies by leading them around the",
      "nose with agile movements.",
      "",
      "These four are the leaders of the",
      "Doppels, and all of them regard",
      "Lucifina as their mother. Their",
      "loyalty to her is absolute, and they",
      "won't hesitate to sacrifice their",
      "lives for her.",
      "",
      "Artist: frfr",
    ],
    658 => [
      "One of the four among the Doppels who",
      "have exceptional abilities. This one",
      "has a steady and serious personality,",
      "and is considered to be the strictest",
      "among the Doppels. She's also",
      "incredibly skilled with a sword and",
      "has an excellent eye for tactics. Her",
      "reliability at carrying out",
      "operations has led her to be highly",
      "trusted by Lucifina.",
      "",
      "These four are the leaders of the",
      "Doppels, and all of them regard",
      "Lucifina as their mother. Their",
      "loyalty to her is absolute, and they",
      "won't hesitate to sacrifice their",
      "lives for her.",
      "",
      "Artist: frfr",
    ],
    659 => [
      "One of the four among the Doppels who",
      "have exceptional abilities. This one",
      "boasts the greatest strength of the",
      "four despite her petite build. Thus,",
      "she is better suited to wielding",
      "striking weapons such as axes and",
      "clubs as opposed to swords. Although",
      "she has a simplistic way of thinking,",
      "she excellent instincts for sensing",
      "danger and is surprisingly able to",
      "lead groups without endangering them.",
      "",
      "These four are the leaders of the",
      "Doppels, and all of them regard",
      "Lucifina as their mother. Their",
      "loyalty to her is absolute, and they",
      "won't hesitate to sacrifice their",
      "lives for her.",
      "",
      "Artist: frfr",
    ],
    660 => [
      "One of the four among the Doppels who",
      "have exceptional abilities. This one",
      "strongly expresses valkyrie",
      "characteristics, and excels at",
      "wielding a spear and controlling holy",
      "energy. She can even form wings with",
      "her holy aura to take flight at high",
      "speeds. Calm and collected and",
      "skilled in leadership, she's the one",
      "who is usually selected as the",
      "commanding officer for very dangerous",
      "missions.",
      "",
      "These four are the leaders of the",
      "Doppels, and all of them regard",
      "Lucifina as their mother. Their",
      "loyalty to her is absolute, and they",
      "won't hesitate to sacrifice their",
      "lives for her.",
      "",
      "Artist: frfr",
    ],
    661 => [
      "One of the Primordial Angels, hailed",
      "as the Daystar. Created as a",
      "fragment of Ilias herself, she",
      "boasts outstanding power unmatched",
      "by anyone in Heaven except for her",
      "older sister, Micaela. She has an",
      "uninhibited personality and has been",
      "known to bring completely",
      "unpredictable disasters upon her",
      "enemies. The Dark Goddess' army",
      "feared Lucifina as a devil, with",
      "some even having taken their own",
      "lives upon hearing word of her",
      "arrival on the battlefield.",
      "",
      "She currently lives in seclusion on",
      "the moon, where she leads an army of",
      "Doppels. Calamity would undoubtedly",
      "ensue if Lucifina herself were to",
      "take direct action, thus the Angelic",
      "Dominion's forces watch the moon",
      "with trepidation.",
      "",
      "Artist: frfr",
    ],
    662 => [
      "An angel belonging to the third",
      "circle of the nine in the angel",
      "hierarchy (Throne). Many of them are",
      "enlisted in San Ilia as the",
      "bodyguards of Raphaela of the Seven",
      "Archangels. They express succubus",
      "genes as Raphaela requested, and",
      "have a lecherous nature. Their very",
      "sexy figures arouse the sexual",
      "desires of the pious Chosen Ones of",
      "San Ilia. Since they are high-ranking",
      "angels, they have incredibly high",
      "combat capabilities and are very",
      "intelligent, with many of them",
      "involved in government affairs under",
      "Raphaela.",
      "",
      "They are among the most lascivious",
      "angels in the Angelic Dominion, and",
      "find the greatest delight in raping",
      "pious believers. They deliberately",
      "corrupt believers that they set their",
      "eyes upon to make them addicted to",
      "their bodies. Even her enemies are",
      "raped without exception, becoming",
      "prey to her intense lust.",
      "",
      "Artist: Saiki",
    ],
    663 => [
      "An angel belonging to the third",
      "circle of the nine in the angel",
      "hierarchy (Throne). Her mission is to",
      "look after giant angel eggs and",
      "fertilize them with the bodies of",
      "select humans. Note that the eggs",
      "themselves are produced by other",
      "egg-laying angels, and Eggiel's role",
      "is solely to fertilize and raise the",
      "eggs.",
      "",
      "The egg is fertilized when an entire",
      "human body is treated like sperm and",
      "taken inside the ovum. The human",
      "being used to fertilize the egg will",
      "experience the utmost pleasure,",
      "soaking in ecstasy as they become",
      "nourishment for a sacred life. Since",
      "the only humans used to fertilize the",
      "eggs are generally women, the angels",
      "born are also female. However, it's",
      "theoretically possible to fertilize",
      "the egg with a male, in which case",
      "it's said a hermaphrodite angel",
      "could be born.",
      "",
      "Artist: Delphinus",
    ],
    664 => [
      "A very unusual type of chimeric",
      "monster that is comprised of two",
      "bodies in one. In order to control a",
      "giant-faced beast was accidentally",
      "born during an experiment, a handler-",
      "type of artificial monster was",
      "created and set on top of it. The",
      "monster riding it controls the giant",
      "beast with mental manipulation, and",
      "are able to rampage about as if they",
      "were one in body and mind. In the end",
      "however, their production cost was",
      "too high and they never got mass-",
      "produced, but some were still created",
      "for breaking through bases when the",
      "time comes to invade the Monster",
      "Realm, and are standing by on Mount",
      "Saint Amos.",
      "",
      "The giant-faced beast is incredibly",
      "voracious and will indiscriminately",
      "prey upon any living thing. However,",
      "she's aware that the semen of human",
      "males is very delicious, and should",
      "she capture a man, she will suck him",
      "dry with her mouth until he spits out",
      "all of his semen, then swallow him",
      "whole.",
      "",
      "Artist: Setouchi",
    ],
    665 => [
      "A roid-type chimeric monster created",
      "by Promestein, she is a simplified",
      "mass-production model of Arc-En-Ciel,",
      "the head of the Next Dolls. While she",
      "boasts outstanding combat performance",
      "even among the chimeric monsters,",
      "she's still nowhere near as powerful",
      "as Arc-En-Ciel. Due to her exorbitant",
      "cost of production, the plans to",
      "mass-produce simplified Arc-En-Ciels",
      "came to an end with the completion of",
      "a single Knightroid. When their data",
      "reached the Angelic Dominion however,",
      "their high performance was noticed,",
      "and a few were mass-produced as",
      "elites for the upcoming invasion of",
      "the Monster Realm.",
      "",
      "Her main weapon is a gigantic spear,",
      "but she is also highly skilled at",
      "wielding a biological whip that has",
      "been assimilated into her left hand.",
      "She's also skilled in sexual",
      "techniques, which she will use to",
      "torment male warriors as if to test",
      "their willpower. Since she was",
      "created using parts from many",
      "warrior-type monsters, she has a",
      "chivalrous spirit and holds a deep",
      "respect towards Arc-En-Ciel as her",
      "senior. On the other hand, she holds",
      "contradictory feelings of contempt",
      "towards the weak, and is said to",
      "thoroughly humiliate anyone who loses",
      "to her.",
      "",
      "Artist: xelvy",
    ],
    666 => [
      "A roid-type chimeric monster",
      "developed for the purpose of",
      "assassinating important people.",
      "Able to assassinate even Queen-class",
      "monsters, she's specialized in",
      "stealth in addition to quiet",
      "performance and lethal strikes. A",
      "special drive mechanism was built",
      "into her to prevent body heat from",
      "escaping and allow her to avoid",
      "detection from monsters that sense",
      "heat to catch their foes, but this",
      "comes with the drawback of needing to",
      "vent the heat immediately after long",
      "periods of activity. In addition to",
      "her normal genitalia, she also has a",
      "secondary tentacle-like genitalia,",
      "though its unclear what this",
      "mechanism's purpose is. Due to their",
      "high cost, mass-production of them",
      "was initially disregarded, but once",
      "their data had reached the Angelic",
      "Dominion, their high performance was",
      "noticed, and a few were mass-produced",
      "as elites for the upcoming invasion",
      "of the Monster Realm.",
      "",
      "In addition to having extremely high",
      "capabilities in regular combat, she's",
      "also mastered all manner of sexual",
      "techniques to subdue opponents who",
      "specialize in head-on combat. She's",
      "very harsh towards the weak, and will",
      "mercilessly rape any man she defeats",
      "in a fight.",
      "",
      "Artist: xelvy",
    ],
    667 => [
      "Eden after having absorbed enormous",
      "amounts of holy energy to transform",
      "into her final form. Her physical",
      "and magical abilities are immense,",
      "and her form is overflowing with an",
      "abundance of female bodies,",
      "tentacles, and sacred trees. She",
      "displays overwhelming power in this",
      "form, but her formerly-calm demeanor",
      "becomes aggressive, and she also",
      "consumes an tremendous amount of",
      "energy in it. While it can't really be",
      "called a runaway form, there is no",
      "doubt that it carries considerable",
      "risks.",
      "",
      "Artist: Setouchi",
    ],
    668 => [
      "An angel belonging to the third",
      "circle of the nine in the angel",
      "hierarchy (Throne). They are the",
      "highest-ranking angels who are",
      "responsible for government affairs in",
      "the Angelic Dominion, and handle many",
      "confidential matters. While they",
      "effectively noncombatants, they",
      "still possess power appropriate for a",
      "angel from the third circle, and",
      "their fighting abilities are far",
      "superior to those of the average",
      "combat angel. Their workloads are",
      "immense, and the burden of their",
      "responsibilities are heavy, causing",
      "their stress to accumulate. All of",
      "them seem quiet and pale-looking, but",
      "the Yuriels were cheerful and bright-",
      "skinned when they were first",
      "appointed, and typically ended up",
      "that way after a year of work.",
      "",
      "Combat is entirely outside of their",
      "line of work, but if they do spot an",
      "enemy, they will strike instead of",
      "taking refuge. They excel at magic",
      "and emanating holy energy, and will",
      "use both to silence intruders with",
      "overwhelming power. Any invaders they",
      "capture are said to be subjected to",
      "harsh rape afterwards.",
      "",
      "Artist: Saiki",
    ],
    669 => [
      "An angel belonging to the third",
      "circle of the nine in the angel",
      "hierarchy (Throne). They have the",
      "ability to purify contaminated air",
      "and water and are experts at",
      "healing. Also, because of the nature",
      "of their duties, they have a deep",
      "knowledge of poisons and",
      "contaminants, and are said to be",
      "able to easily interfere with",
      "elements to break down pollutants,",
      "or conversely create them. They",
      "appear to be relatively new angels",
      "that were created to reduce",
      "pollution caused by internal",
      "combustion engines used in parts of",
      "the Angelic Dominion as its",
      "population increased. Their",
      "production costs are incredibly high",
      "however, and their numbers aren't",
      "keeping up with the demand, so",
      "reducing their costs appears to be a",
      "major issue.",
      "",
      "While combat isn't their primary",
      "role, their basic abilities are high",
      "overall, and they can be called upon",
      "to eliminate invaders. The viscous",
      "fluids dripping from their entire",
      "bodies can be used for both offense",
      "and defense. It also absorbs energy",
      "from any opponent wrapped in it to",
      "restore their power. Should their",
      "target be a man, the fluid will suck",
      "up every last drop of his semen.",
      "",
      "Artist: Delphinus",
    ],
    670 => [
      "An angel belonging to the third",
      "circle of the nine in the angel",
      "hierarchy (Throne). To prepare for",
      "the coming Second Great Monster Wars,",
      "this angel was designed to have high",
      "close-combat capabilities in addition",
      "to being possible to mass-produced at",
      "low cost. As a result, a production",
      "cost that is roughly half of that of",
      "combat angels within the same rank",
      "was achieved with Sebasiel. With the",
      "clash against the Dark Goddess",
      "imminent, their production appears to",
      "be advancing at a furious pace.",
      "",
      "Their very bodies are swords, which",
      "combine high durability with quick",
      "maneuverability, granting them",
      "extremely high combat capabilities.",
      "Furthermore, they are highly",
      "cooperative, able to fully utilize",
      "their strengths in groups to pose a",
      "significant threat to their enemies.",
      "Perhaps as a tradeoff for their",
      "low cost, they take in less holy",
      "energy from the atmosphere compared",
      "to other angels, and must supplement",
      "supplement their energy expenditure",
      "by consuming meat. Enemies defeated",
      "by them will be absorbed into their",
      "bodies, tasting pleasure as they",
      "become a part of them.",
      "",
      "Artist: Delphinus",
    ],
    671 => [
      "To prepare for the coming battle",
      "against the Dark Goddess' Army, plans",
      "had emerged to mass-produce the",
      "incredibly-costly Next Dolls. By",
      "applying technology unique to the",
      "Angelic Dominion, their expensive",
      "resources were substituted with ones",
      "derived from chaos to achieve lower",
      "cost. Their high combat abilities are",
      "on par with the original Next Dolls,",
      "but the chaos materials comprising",
      "most of their bodies places heavy",
      "strain on them, causing them to",
      "disintegrate after six months.",
      "While this would be considered an",
      "unacceptable service life for an",
      "ordinary war machine, it appears",
      "various plans are being searched for,",
      "such as timing their completion to",
      "coincide with the final battle",
      "against the Monster Realm.",
      "",
      "Artist: Thomas",
    ],
