      "such as timing their completion to",
      "coincide with the final battle",
      "against the Monster Realm.",
      "",
      "Artist: Thomas",
    ],
    675 => [
      "To prepare for the coming battle",
      "against the Dark Goddess' Army, plans",
      "had emerged to mass-produce the",
      "incredibly-costly Next Dolls. By",
      "applying technology unique to the",
      "Angelic Dominion, their expensive",
      "resources were substituted with ones",
      "derived from chaos to achieve lower",
      "cost. Their high combat abilities are",
      "on par with the original Next Dolls,",
      "but the chaos materials comprising",
      "most of their bodies places heavy",
      "strain on them, causing them to",
      "disintegrate after six months.",
      "While this would be considered an",
      "unacceptable service life for an",
      "ordinary war machine, it appears",
      "various plans are being searched for,",
      "such as timing their completion to",
      "coincide with the final battle",
      "against the Monster Realm.",
      "",
      "Artist: Thomas",
    ],
    676 => [
      "An angel belonging to the second",
      "circle of the nine in the angel",
      "hierarchy (Cherubim). After the",
      "Whiteyels' combat abilities had been",
      "drastically enhanced as a result of",
      "receiving Ilias' favor, similar",
      "angels had begun to be created as",
      "combat types. Holmiel was created as",
      "a result of this, a humanoid angel",
      "without a deformed body, but endowed",
      "with the highest levels of combat",
      "prowess in the Angelic Dominion.",
      "She excels in hand-to-hand combat and",
      "possess great control over holy",
      "energy. She also has great leadership",
      "skills, making her a reassuring",
      "presence as a pure combat type. Many",
      "of them comprise the Goddess' elite",
      "guard at the Ilias Temple, and some",
      "have been selected to serve as",
      "division commanders.",
      "",
      "Holmiels have fierce and competitive",
      "personalities compared to the calm",
      "and earnest Whiteyels. They will",
      "utterly beat down the Goddess'",
      "enemies and inflict merciless",
      "punishment upon them.",
      "",
      "Artist: Arekishi",
    ],
    677 => [
      "An angel belonging to the third",
      "circle of the nine in the angel",
      "hierarchy (Throne). To prepare for",
      "the coming Second Great Monster",
      "Wars, a decision was made to begin",
      "experimental development of angels",
      "made from chaos materials. The",
      "completed Aptiel has extremely high",
      "basic abilities all-around, boasting",
      "ideal capabilities for a combat",
      "angel, but she has an unstable",
      "personality and poses a risk of",
      "going out of control. She was simply",
      "a test model and no plans were made",
      "to mass-produce her, but a fair",
      "number of them are being maintained",
      "due to having divided herself.",
      "While they aren't able to carry out",
      "complex missions, they're allowed to",
      "roam about freely in the Ilias",
      "Temple as defense forces due to",
      "their tendency to attack any",
      "unregistered individuals who",
      "approach them.",
      "",
      "Upon discovering unregistered",
      "intruders, they will attack to",
      "incapacitate them, then take them",
      "into their bodies. Their pitiful",
      "prey will be immersed in ecstasy as",
      "they are swallowed in a vortex of",
      "chaos. It should be noted that they",
      "not only attack intruders, but even",
      "angels who they should have",
      "registered as well.",
      "",
      "Artist: frfr",
    ],
    678 => [
      "An angel belonging to the third",
      "circle of the nine in the angel",
      "hierarchy (Throne). To prepare for",
      "the coming Second Great Monster Wars,",
      "plans emerged to produce large",
      "numbers of inexpensive combat angels",
      "based on existing creatures. Several",
      "types of angel designs were tested,",
      "but the beast-types, which were",
      "considered to be the most likely",
      "candidates, were dropped due to their",
      "high cost. The disappointment",
      "continued with insect-types proving",
      "to have low intelligence which made",
      "them too inflexible, but surprisingly",
      "the clione-type angels showed",
      "extremely good performance. They have",
      "high physical and magical abilities,",
      "are quiet but obey commands, and have",
      "started being produced as remarkably",
      "excellent fighting forces. However,",
      "the Second Great Monster Wars began",
      "sooner than anticipated, and there",
      "was only enough time to have them",
      "deployed at the Ilias Temple as a",
      "result.",
      "",
      "They are exceptionally greedy despite",
      "their taciturn nature, and their only",
      "flaw is that they will devour any",
      "targets, even when their mission is",
      "just to capture. Like the cliones",
      "they're based on, they extend buccal",
      "cones from their heads to swallow",
      "captured enemies whole. The prey",
      "will experience supreme pleasure",
      "as they're digested inside the",
      "Clionera's body.",
      "",
      "Artist: Mizukichi",
    ],
    679 => [
      "An angel belonging to the second",
      "circle of the nine in the angel",
      "hierarchy (Cherubim). When the",
      "encroachment of chaos was confirmed in",
      "various locations of the Angelic",
      "Dominion, the Goddess Ilias halted",
      "its spread by freezing time around",
      "it. Furthermore, she had set out to",
      "create angels that could support her",
      "in this task. In doing so, she had",
      "completed Roseniel, a top-ranking",
      "angel who excels at manipulating",
      "time. She possesses time manipulation",
      "abilities far exceeding levels",
      "permitted to angels up until now, and",
      "is expected to play a role in",
      "preventing future chaos encroachment.",
      "Nevertheless, it became clear that",
      "the production of Roseniel was also",
      "just a makeshift solution, and would",
      "only buy some time. She gets along",
      "well with the Cherub Cubeiel, who",
      "was also created for the same",
      "purpose, but by contrast, she has",
      "almost no interactions with other",
      "angels since they're so different",
      "from her.",
      "",
      "She is always standing by at the",
      "Ilias Temple as part of her duty.",
      "In the unlikely event an enemy were",
      "to break into the temple, Roseniel",
      "would be tasked with intercepting",
      "them as well. While she wasn't",
      "intended to be a combatant, there's",
      "no doubting that her ability to",
      "manipulate time would display",
      "outstanding power in battle.",
      "",
      "Artist: Delphinus",
    ],
    680 => [
      "An angel belonging to the second",
      "circle of the nine in the angel",
      "hierarchy (Cherubim). When the",
      "encroachment of chaos was confirmed in",
      "various locations of the Angelic",
      "Dominion, the Goddess Ilias halted",
      "its spread by freezing time around",
      "it. Furthermore, she had set out to",
      "create angels that could support her",
      "in this task. In doing so, she had",
      "completed Cubeiel, a top-ranking",
      "angel who excels at manipulating",
      "space. She possesses spatial",
      "manipulation abilities far exceeding",
      "levels permitted to angels up until",
      "now, and is expected to play a role",
      "in preventing future chaos",
      "encroachment. Nevertheless, it became",
      "clear that the production of Cubeiel",
      "was also just a makeshift solution",
      "and would only buy some time. She",
      "gets along well with the Cherub",
      "Roseniel, who was also created for",
      "the same purpose, but by contrast,",
      "she has almost no interactions with",
      "other angels since they're so",
      "different from her.",
      "",
      "She is always standing by at the",
      "Ilias Temple as part of her duty.",
      "In the unlikely event an enemy were",
      "to break into the temple, Cubeiel",
      "would be tasked with intercepting",
      "them as well. While she wasn't",
      "intended to be a combatant, there's",
      "no doubting that her ability to",
      "manipulate space would display",
      "outstanding power in battle.",
      "",
      "Artist: Delphinus",
    ],
    681 => [
      "An angel belonging to the second",
      "circle of the nine in the angel",
      "hierarchy (Cherubim). She doesn't",
      "have a specific duty, and is",
      "dispatched in situations where the",
      "angels in charge are unable to handle",
      "it, making her a reserve force so to",
      "speak. She thinks of humans and",
      "monsters as nothing but specks of",
      "dust, and is exceptionally ruthless",
      "even among the angels who generally",
      "look down down upon all living things",
      "that aren't angels.",
      "",
      "Her powers are beyond human",
      "comprehension, to the extent that",
      "simply descending upon the surface",
      "world erodes the space around her.",
      "When dealing with the Godddess'",
      "enemies, she has the ability to",
      "swallow up thousands of humans and",
      "monsters all at once with her worm-",
      "like body. Horrific violation awaits",
      "sinners who are taken inside her like",
      "this as they are toyed with and",
      "killed. In addition, the female",
      "portion of her body is also made up",
      "of worms, and her true form is the",
      "aggregation of all of the worms",
      "comprising her bizarre body.",
      "",
      "Artist: Delphinus",
    ],
    682 => [
      "The Artificial Spirits were created",
      "for the purpose of stabilizing",
      "nature, but because of the extremely",
      "potent magic they possess out of",
      "necessity, plans were made to mass-",
      "produce them as next-generation",
      "fighting units in anticipation of the",
      "second Great Monster Wars. Following",
      "that, although an experimental mass-",
      "production model was created, the",
      "production costs were far greater",
      "than expected. In the end, only a",
      "small number were manufactured, and",
      "the plans were scrapped.",
      "",
      "The few mass-produced Artificial",
      "Spirits that did get created were",
      "stationed in the Ilias Temple, the",
      "most important stronghold in the",
      "Angelic Dominion. Not only are their",
      "production costs steep, the cost to",
      "run them are also high, and they",
      "require large amounts of energy to",
      "function. Fortunately, sinners exist",
      "in infinite numbers in the Dominion",
      "as if they're free energy, so this",
      "doesn't appear to be a problem for",
      "the time being.",
      "",
      "Artist: UN_DO",
    ],
