    729 => [
      "A multipurpose cat-type robot that",
      "was mass-produced in Yamatai. They",
      "are completely autonomous and claim",
      "to have wills of their own. They are",
      "responsible for all kinds of",
      "miscellaneous tasks in Yamatai, and",
      "are versatile, handling everything",
      "from infrastructure management to",
      "customer service. They also have",
      "combat capabilities and are armed",
      "with weapons far too powerful for",
      "just self-defense. Their friendly and",
      "free-spirited personalities were not",
      "intentionally programmed into them,",
      "but rather something learned",
      "automatically. Through interacting",
      "with many people, they've adopted",
      "a self-paced money-focused nature",
      "that exude charm. Nevertheless, they",
      "perform well, protecting the",
      "livelihoods, social infrastructure,",
      "and safety of Yamatai's citizens.",
      "In recent years, they have begun to",
      "make political claims calling for",
      "robots to be granted human rights,",
      "and have even gone so far as to",
      "staged demonstration marches.",
      "",
      "They are regularly supplied with",
