      "legs.",
      "",
      "Artist: xelvy",
    ],
    730 => [
      "A combat-type android based on a",
      "kitsune with powerful weapons and a",
      "small magic reactor built into her.",
      "In addition to having expert sword",
      "skills, the magical power supplied",
      "from her reactor also allows her to",
