      "to be active in that role. They have",
      "warrior-type personalities and value",
      "honor on the battlefield. They get",
      "along poorly with most ordinary",
      "harpies and are disliked by them as",
      "being a violent and boorish flock.",
      "",
      "Although they think in a militaristic",
      "way, they aren't necessarily cruel.",
      "They capture young, healthy men",
      "during their breeding season to mate",
      "with them, but won't inflict any",
      "unnecessary harm upon them. Once the",
