    734 => [
      "A mighty bird monster known to be",
      "among the most powerful yoma in the",
      "Monster Realm, they are a famous",
      "ancient species that possess",
      "tremendous power within themselves.",
      "It's said that the first monsters",
      "created by Saja of the Six Ancestors",
      "were Jormungandr and Archaeopteryx,",
      "who strongly expressed the traits of",
      "snakes and birds respectively and",
      "branched off into the lamias and",
      "harpies. Most Archaeopteryx live in",
