    ],
    735 => [
      "The Queen of the Harpy race, renowned",
      "for her military prowess. Her",
      "strength and valor echo across the",
      "entire Monster Realm, and she has",
      "been assembling the militant faction",
      "of her clan to push forward on a path",
      "to domination. She is an expert with",
      "spear techniques and boasts combat",
      "prowess capable of even overwhelming",
      "other Queen-level opponents. However,",
      "her repeated foreign campaigns have",
      "led to opposition from moderates",
      "within her race, and the harpies",
      "have become divided in recent years.",
      "",
      "Despite her very belligerent",
      "disposition, she enjoys pampering men",
