    ],
    739 => [
      "A half-beast mermaid that has",
      "acquired a strong resistance to the",
      "oceanic pollution caused during the",
      "Great Monster Wars. They are highly",
      "ferocious mermaids with great,",
      "vitality and sturdiness, and have",
      "inherited characteristics of the",
      "Narwhal Girl, though they have",
      "smaller bodies. There are several",
      "unknown factors regarding their",
      "evolutionary lineage, with some",
      "suggesting that they may have mutated",
      "from their polluted environment.",
      "Most Great Mermen live freely out in",
      "the seas, but there are some who have",
      "cast themselves among the ranks of",
      "pirate crews. The Roza Pirates in",
      "particular, the largest pirate crew",
      "in the Monster Realm, have recruited",
      "several Great Merman as their raiding",
      "forces. Their days of fight after",
      "fight suit their ferocious nature,",
      "and they appear to enjoy the pirate",
      "life.",
      "",
      "They are incredibly violent when they",
      "rape men, and even when they don't",
      "intend to cause harm, they end up",
