      "are said to have exceptional sexual",
      "prowess, and will sometimes rape",
      "multiple men at once during pirate",
      "feasts.",
      "",
      "Artist: Setouchi",
    ],
    740 => [
      "The captain of the Roza Pirates, the",
      "pirate crew named after herself which",
      "is the largest in the Monster Realm.",
      "Her alias of \"Pirate Queen\" is",
      "renowned throughout the Realm, and",
      "her ferocity is said to be unmatched",
      "out at sea. Without siding with any",
      "of the Six Ancestors, she used the",
      "seas as her base and attacked port",
      "town all over the world, and through",
      "repeated plundering, had built up",
      "power equivalent to a small nation.",
      "Possessing personal bravery, command",
      "over naval battles, and shrewdness to",
      "navigate the rough seas woven by the",
      "ambitions of major powers, her",
      "abilities as a pirate captain are",
      "unprecedented in history. However,",
      "there are concerns that the Roza",
      "Pirates are overly reliant on the",
      "abilities of Captain Roza, and that",
      "there are no promising future leaders",
      "rising among their ranks.",
      "",
      "Following plunders, the man deemed to",
      "be of the highest quality becomes the",
      "captain's property. After spending",
      "the night milking his semen dry",
      "however, she immediately lets the man",
      "go free. It's said she's never had a",
