    773 => [
      "High-ranking succubi who aspire to",
      "be dancers. They live in groups as a",
      "caravan, wandering all around the",
      "Monster Realm like nomads. Many of",
      "them come from aristocratic",
      "upbringings, said to have grown bored",
      "of the glamorous social life and",
      "escaped the city seeking freedom.",
      "Since they travel around the Monster",
      "Realm, they possess considerable",
      "fighting capabilities in order to",
      "protect themselves. Their graceful",
      "movements utilizing their well-",
      "trained bodies are useful in battle,",
      "and their dances yield various",
      "effects that let them toy with their",
      "enemies. They're also masters at the",
      "art of charm, and are easily able to",
      "send lowly bandits packing.",
      "",
      "Whenever one sees a man during her",
      "travels, she will seduce him, then",
      "have sex with him to drain his",
      "energy. High-quality catches are",
