      "few more of them. They are stationed",
      "in their master's base, the Black",
      "Mansion, as one last trump card.",
      "",
      "Artist: UN_DO",
    ],
    789 => [
      "One of the Monster Lord Puppets",
      "created by Kagetsumugi using the",
      "corpses of past Monster Lords. Since",
      "she was the mother of Black Alice who",
      "Kagetsumugi respects and admires, she",
      "has been treated with special care",
      "and rather than detracting from the.",
      "gaudy appearance she had in life, she",
      "was made to look even more alluring.",
      "In addition to having great magical",
      "power, she poses a threat with the",
      "attacks from her countless blooming",
      "flowers. Skilled with a whip and able",
      "to assault minds with her pollen, she",
      "is an extremely troublesome puppet.",
      "",
      "After the Monster Lord Puppets were",
      "completed, lower-grade materials and",
      "core duplication technology were",
      "used to successfully mass-produce a",
      "few more of them. They are stationed",
      "in their master's base, the Black",
      "Mansion, as one last trump card.",
      "",
      "Artist: UN_DO",
    ],
    790 => [
      "One of the Monster Lord Puppets",
      "created by Kagetsumugi using the",
      "corpses of past Monster Lords. Since",
      "she was Black Alice's younger sister,",
      "her appearance ended up being",
      "modelled after her. For someone who",
      "sincerely loathed her older sister,",
      "she would've surely found this",
      "objectionable. In addition to her",
      "outstanding ability to control",
      "darkness, she is also just as",
      "matchless with a spear as she was",
      "when she was alive. Among the Monster",
      "Lord Puppets, this one boasts",
      "excellent cutting abilities and is",
      "the one Kagetsumugi is most proud of.",
      "",
      "After the Monster Lord Puppets were",
      "completed, lower-grade materials and",
      "core duplication technology were",
      "used to successfully mass-produce a",
      "few more of them. They are stationed",
      "in their master's base, the Black",
