      "",
      "Artist: UN_DO",
    ],
    791 => [
      "One of the Monster Lord Puppets",
      "created by Kagetsumugi using the",
      "corpses of past Monster Lords. The",
      "theme for this one was \"Erosion of",
      "Time\", and her figure was",
      "deliberately regressed to the form",
      "of a young girl. In addition to her",
      "time magic and dark arts, her",
      "attacks utilizing her insect organs",
      "are all very powerful. Her insect",
      "carapace also provides great",
      "defense, making her incredibly",
      "durable for a mage-type puppet.",
      "",
      "After the Monster Lord Puppets were",
