      "few more of them. They are stationed",
      "in their master's base, the Black",
      "Mansion, as one last trump card.",
      "",
      "Artist: UN_DO",
    ],
    792 => [
      "One of the Monster Lord Puppets",
      "created by Kagetsumugi using the",
      "corpses of past Monster Lords. The",
      "heavily-damaged remains of the 11th",
      "and 12th Monster Lords have been",
      "conjoined and decorated in a manner",
      "fitting for a circus. The",
      "characteristics that the two had in",
      "life however have been mostly lost,",
      "and they're now just puppets that",
      "fight solely with their strong",
      "physical abilities and coordinated",
      "two-body attacks. Their autonomous",
      "drive system also doesn't function",
      "properly due to issues with the",
      "two's thought links, causing them to",
      "be mentally broken. Frankly",
      "speaking, this was a failure, but",
      "Kagetsumugi refuses to admit it,",
      "insisting that their theme is \"The",
      "Dissonance Woven from Madness and",
      "Imbalance\".",
