      "",
      "Artist: UN_DO",
    ],
    793 => [
      "One of the Monster Lord Puppets",
      "created by Kagetsumugi using the",
      "corpses of past Monster Lords.",
      "Despite the fact she was a recent",
      "Monster Lord, it took longer for",
      "Kagetsumugi to track own her remains",
      "due to there being very few legends",
      "about her. In the end, she found her",
      "buried beneath a certain garden.",
      "Inspired by the sight of that garden,",
      "Kagetsumugi styled her after it",
      "when designing her.",
      "",
      "After the Monster Lord Puppets were",
      "completed, lower-grade materials and",
      "core duplication technology were",
      "used to successfully mass-produce a",
      "few more of them. They are stationed",
      "in their master's base, the Black",
      "Mansion, as one last trump card.",
      "",
      "Artist: UN_DO",
    ],
    794 => [
      "One of the Monster Lord Puppets",
      "created by Kagetsumugi using the",
      "corpses of past Monster Lords. To",
      "tie her in with the legends saying",
      "that she was filled with childlike",
      "naïvete and playfulness, she was",
      "modelled to look like a young girl.",
      "She is a mage-type built with a",
      "special magical reactor made to",
      "replicate the immense magical powers",
      "that she had.",
      "",
      "After the Monster Lord Puppets were",
      "completed, lower-grade materials and",
      "core duplication technology were",
      "used to successfully mass-produce a",
      "few more of them. They are stationed",
      "in their master's base, the Black",
      "Mansion, as one last trump card.",
      "",
      "Artist: UN_DO",
    ],
    795 => [
      "After losing all of her spare bodies,",
      "Kagetsumugi put her remaining",
      "materials to use in constructing this",
      "final body. By also combining parts",
      "from the destroyed Yomigumo and Kaiko",
      "Kitsune, she has drastically improved",
      "her fighting capabilities over her",
      "previous body. Its appearance,",
      "however, is not up to Kagetsumugi's",
      "aesthetic tastes, and she personally",
      "seems very dissatisfied with how it",
      "turned out. No spare parts exist for",
      "this body, making it a truly one-of-",
      "a-kind custom body.",
      "",
      "This body also has very poor fuel",
      "efficiency, requiring an amount of",
      "energy equaling ten adult men's worth",
      "of semen just to fight for one hour.",
      "It is an incredibly fiendish combat",
      "body that needs to squeeze many men",
      "to death in order to remain fully",
      "operational.",
      "",
      "Artist: UN_DO",
    ],
    796 => [
      "Kagetsumugi's final puppet, which",
      "inherits parts from the destroyed",
      "Yomigumo, Kaiko Kitsune, and",
      "Rantengu. She boasts overwhelming",
      "combat capabilities surpassing the",
      "performance of all three of them, but",
      "cost was disregarded in her creation",
      "since she was made to be used for a",
      "decisive battle, so she wouldn't be",
      "able to make this same puppet again.",
      "She has sturdy armor, is extremely",
      "agile, and can cast taoism spells",
      "continuously. Her AI is also",
      "integrated with Kagetsumugi's final",
      "form, allowing the two to perform",
      "combination attacks with perfect",
      "synergy. While she is semi-",
      "autonomous, she doesn't quite appear",
      "to be capable of complex thinking.",
      "",
      "Her fuel efficiency is also extremely",
      "poor, and she requires the semen of",
      "numerous men to function. She leans",
      "over men like she's mating and",
      "violates them to replenish her",
      "energy, ruthlessly extracting their",
      "semen until they are completely",
      "drained. She is a truly sinister",
      "puppet who runs on draining people's",
      "life, and by the time she had gone to",
      "the decisive battle with",
      "Kagetsumugi, she had already sucked",
      "the energy out of a considerable",
      "number of humans.",
      "",
      "Artist: UN_DO",
    ],
    797 => [
      "The Eighth Monster Lord who has",
      "become the Third Goddess. Her",
      "inherent tendencies towards causing",
      "devastation have been further",
      "accelerated by her absorption of",
      "chaos. Now she has become a",
      "transcendent being of catastrophe",
      "who enjoys seeing parallel worlds",
      "meet their ends. Able to wield both",
      "holy and dark energy simultaneously,",
      "she possesses unbelievable power",
      "rivalling the other two goddesses.",
      "She is capable of destroying the",
      "world all by herself, making her the",
      "greatest threat that is currently",
      "known to exist.",
      "",
      "Artist: Setouchi",
    ],
    798 => [
      "An automatically-generated",
      "extermination system for eliminating",
      "intruders from the forbidden areas of",
      "chaos. It was created based on the",
      "White Rabbit's data, and while it has",
      "no ego, it still has incredibly high",
      "combat capabilities. It will continue",
      "to function automatically until it",
      "either eliminates the intruder or is",
      "destroyed.",
      "",
      "Artist: Silk",
    ],
