    805 => [
      "An automatically-generated",
      "extermination system for eliminating",
      "intruders from the forbidden areas of",
      "chaos. It's unknown why it has taken",
      "on Sonya's appearance, but this could",
      "be due to the effects of an irregular",
      "error in the central extermination",
      "system.",
      "",
      "Artist: xelvy",
    ],
    806 => [
      "A high-ranking extermination",
      "individual that manifests to",
      "eliminate intruders from the",
      "forbidden areas of chaos. It could be",
      "considered the avatar of the",
      "extermination system itself and is",
      "said to be part of the central",
      "system comprising the Fifth Law, but",
      "the specifics are unknown.",
      "",
      "Artist: xelvy",
    ],
    807 => [
      "Top-ranking yoma from the strongest",
      "units serving directly under the",
      "Dark Goddess, they are the elite",
      "among the elite. These stone statue",
      "monsters are endowed with immense",
      "magical power, keeping their enemies",
      "at bay using the highest-level",
      "spells. With their ability to turn",
      "living beings into stone as well,",
      "they live up to their reputation as",
      "elite forces. Additionally, during",
      "the battle at the Calamity Star",
      "Demiurge, they were stationed inside",
      "the Calamity Star at the Dark",
      "Goddess' command, and were not",
      "Hiruko's subordinates.",
      "",
      "Like most monsters, she is extremely",
      "greedy for human semen. On top of",
      "that, her lacking sense of time",
      "characteristic of high-ranking yoma",
      "makes her even more dangerous. Should",
      "she take a liking to a man, he will",
      "be petrified while still having sex",
      "with her, and she will subject him",
      "to constant rape to amuse herself for",
      "thousands of years.",
      "",
      "Artist: Arekishi",
    ],
    808 => [
      "Top-ranking yoma from the strongest",
      "units serving directly under the",
      "Dark Goddess, they are the elite",
      "among the elite. They are a newer",
      "monster species that appeared",
      "following the Great Monster Wars who",
      "have been confirmed to carry angel",
      "genes. Despite being a more recent",
      "species, their strength rivals that",
      "of more ancient species and their",
      "combat prowess with a spear is said",
      "to be exceptional. This is why they",
      "have been selected to serve under the",
      "Dark Goddess' elite units, though",
      "there are jealous monsters who gossip",
      "behind their backs, calling them",
      "\"angel-breeds\". Additionally, during",
      "the battle at the Calamity Star",
      "Demiurge, they were stationed inside",
      "the Calamity Star at the Dark Goddess'",
      "command, and were not Hiruko's",
      "subordinates.",
      "",
      "Because of their large builds, their",
      "energy consumption is steep, so they",
      "are incredibly greedy. When they have",
      "sex with men, they will remain",
      "together for three days and three",
      "nights without parting from them.",
      "Their partners often die from",
      "exhaustion as a result of this.",
      "Despite having the demeanor of",
      "warriors, they are extremely",
      "dangerous monsters who cannot control",
      "their own desires.",
      "",
      "Artist: Setouchi",
    ],
    809 => [
      "Lilith, having lost her sisters",
      "Astaroth and Morrigan, has",
      "returned to her original, true",
      "power. Originally, Lilith was an",
      "exceptionally powerful succubus",
      "created from Minagi. However, due",
      "to her immense magical power being",
      "uncontrollable, she was forced to",
      "split into three beings: Lilith,",
      "Astaroth, and Morrigan, forming",
      "the trio of sisters. With the",
      "deaths of Astaroth and Morrigan,",
      "the divided power has returned to",
      "Lilith, reviving her former self",
      "as the great succubus she once",
      "was.",
      "",
      "The previously unstable magical",
      "power has now stabilized, as",
      "Lilith has enhanced her own",
      "capabilities. However, the anger",
      "and sorrow from losing both her",
      "sisters and Minagi have left her",
      "emotionally unstable. Being",
      "violated by Lilith in her",
      "heightened state would mean",
      "certain death. She would drain",
      "one's life force entirely,",
      "consuming it as mere sustenance",
      "while delivering overwhelming",
      "pleasure, leaving her victims to",
      "perish almost instantly.",
      "",
      "Artist: Shiki",
    ],
    810 => [
      "An individual split from Erubetie,",
      "one of the Four Heavenly Knights of the",
      "Monster Lord's Army. Naturally, their",
      "power is inferior compared to the main",
      "body, but they still boast power equal",
      "to or greater than high-ranking slimes.",
      "Since Erubetie is an aggregation of",
      "over 10,000 wills, she is able to",
      "create several hundreds--even thousands",
      "of split bodies with this level of",
      "power.",
      "",
      "Artist: Kenkō Cross",
    ],
    811 => [
      "Erubetie, one of the Four Heavenly",
      "Knights of the Monster Lord's Army,",
      "after taking in the cells of the",
      "slime race's ancestor Kanade, has",
      "attained this form and powered up",
      "immensely. Her vitality and division",
      "abilities have grown explosively, and",
      "her combat abilities have drastically",
      "increased. However, the purpose of",
      "this enhancement was not for battle,",
      "but for assimilating all life with",
      "herself in the Singularity World.",
      "This has placed a heavy mental burden",
      "upon her, and has made her unstable.",
      "She shuts her eyes to everything",
      "else, and presses onward with her",
      "objective solely for the sake of her",
      "slime brethren.",
      "",
      "Artist: Kenkō Cross",
    ],
    812 => [
      "A pair of komainu monsters that act",
      "as one who are revered in Yamatai,",
      "they are of an ancient beast species",
      "that boasts overwhelming power. They",
      "also have high magical powers and can",
      "can use powerful taoism. They are",
      "typically friendly towards humans and",
      "will protect the weak, and it is for",
      "this reason that they are worshipped",
      "as guardian deities by the people of",
      "the villages and towns in the Yamatai",
      "region. Additionally, the one with",
      "the open mouth named \"A\" is",
      "ferocious and energetic, while the",
      "other one named \"Un\" is gentle and",
      "motherly.",
      "",
      "In villages under the protection of",
      "Aun, an annual festival is held where",
      "a man born under the same sign as",
      "that year is chosen to share a bed",
      "with them. Unlike a sacrifice, the",
      "man's life is never taken and he gets",
      "to enjoy an entire week filled with",
      "pleasure each day, so the position of",
      "those born under a festival's sign is",
      "something the village men long for.",
      "",
      "Artist: Jingai Modoki",
    ],
    813 => [
      "A very rare dragon species that has",
      "manifested a dragon's head on one",
      "of her arm. In addition to spewing",
      "fire and ice breath, this head's",
      "fangs can also deliver extremely",
      "powerful bites. She is also an",
      "excellent monster swordswoman,",
      "whose combined assaults of powerful",
      "sword skills and dragon head attacks",
      "make her incredibly strong. Some of",
      "them are active mercenaries, but most",
      "appear to belong to units serving",
      "directly under the Dark Goddess and",
      "are patrolling the Monster Continent.",
      "",
      "The dragon's head on her arm is even",
      "more gluttonous than her main body,",
      "and will crave semen whenever it sees",
      "a man. As part of her pride as a",
      "warrior, she will negotiate with",
      "civilian men for consent to let it",
      "to drink their semen. Most don't",
      "refuse, and will offer up large",
      "amounts of semen in exchange for",
      "pleasure. When milking semen from",
      "an enemy however, this becomes",
      "harsh torture. They're said to",
      "squeeze as much semen as possible",
      "from their enemies, occasionally",
      "even taking their lives in doing so.",
      "",
      "Artist: Cool-kyou Shinja",
    ],
    814 => [
      "A huge whale monster who dominates",
      "the seas. Although she is technically",
      "a mermaid, her extraordinarily large",
      "body grants her overwhelming",
      "destructive power. Conversely, her",
      "magical organs appear to have",
      "atrophied. She also has the toughness",
      "and vitality to withstand polluted",
      "seas.",
      "",
      "They instinctively patrol around",
      "coasts and will show up wherever they",
      "can spot a port town where they will",
      "be warmly welcomed by the residents,",
      "then quietly swim away satisfied. On",
      "these occasions, Monstros will present",
      "gifts such as large pearls and rare",
      "corals, so the the costs of",
      "providing them hospitality are more",
      "than recouped in return. Should they",
      "be ignored or treated rudely however,",
      "they will go on a rampage and sink",
      "every ship there. When treated poorly",
      "they bring about disaster, but when",
      "welcomed properly, they are great sea",
      "beasts that the residents",
      "appreciate.",
      "In addition, they have been landing",
      "upon the Monster Continent for some",
      "reason and running wild. They are",
      "very excitable at these moments, so",
      "it's best not to approach them.",
      "",
      "Artist: Cool-kyou Shinja",
    ],
    815 => [
      "A high-ranking yoma that has been",
      "revered as a god since ancient times,",
      "and a warrior boasting some of the",
      "greatest power in the Monster Realm.",
      "Extremely skilled in combat, they",
      "wields a weapon in each of her",
      "multiple arms to annihilate foes with",
      "overwhelming force. They are revered",
      "as Earth Mothers in their homeland,",
      "and remains very famous to this day.",
      "When people in the Monster Realm",
      "think of powerful monsters, Shiva",
      "is mentioned by most of them. Many",
      "of them hold distinguished combat",
      "occupations, such as serving the Dark",
      "Goddess as her elite guard.",
      "",
      "They're overflowing with vigor and",
      "sexual desire, but since no man would",
      "dare set foot upon the Dark Goddess'",
      "Castle, they're always starving for",
      "men. They appear to visit brothels on",
      "their rare days off to squeeze out as",
      "much semen as they want. Sometimes,",
      "their pent-up energy causes problems",
      "when they engage in violent conduct.",
      "Surprisingly, rather than directly",
      "having sex with their prey, they use",
      "their multiple arms to play with his",
      "erogenous zones and drive him into",
      "agonizing pleasure. His overflowing",
      "semen will then be the sweetest",
      "nectar of all to them.",
      "",
      "Artist: makiya",
    ],
    816 => [
      "A high-ranking wizard who is said to",
      "be among the top three in the Monster",
      "Realm. She is also a notorious",
      "schemer, and upon the arrival of",
      "Ilias and her party in the Monster",
      "Realm, she managed to capture the",
      "Singularity World's Mephisto and slip",
      "into her place. However, she somehow",
      "managed to escape after she was",
      "discovered to be a spy in the",
      "Calamity Star.",
      "",
      "From that point on, she kept watch",
      "over the Singularity World's",
      "Mephisto, who was being confined in",
      "the Sealed Sinner's Prison. She was",
      "plotting revenge against Luka and",
      "his party who would come to the",
      "rescue. That said, this behavior was",
      "very uncharacteristically lacking in",
      "her usual composure.",
      "",
      "Artist: UN_DO",
    ],
    817 => [
      "A composite sea-dwelling monster that",
      "lurks in the ocean's depths. With her",
      "sturdy body that withstands water",
      "pressure, vitality that is unaffected",
      "by pollution, as well as many large",
      "tentacles and a tough shell, she",
      "reigns as the unrivaled queen of the",
      "deep sea. Now that the second Great",
      "Monster Wars are approaching, they",
      "are being recruited into the Dark",
      "Goddess' army for their fighting",
      "prowess. They emerged from the sea in",
      "response to their invitation,",
      "becoming powerful guardians that",
      "protect the Dark Goddess' Castle.",
      "Additionally, Kraken and Poseidoness,",
      "the Queens of the Seas in the",
      "Singularity World are said to be",
      "descendants of the Neptunes. The",
      "Neptune clan is already extinct in",
      "the Singularity World, and it's",
      "very likely that they were targetted",
      "by the Goddess Ilias to be",
      "exterminated.",
      "",
      "Should the Dark Goddess' Castle be",
      "assaulted, the Neptunes will repel",
      "the invaders with their overwhelming",
      "offensive might. Should any of the",
      "invaders be a man, he will certainly",
      "be subjected to violent rape. After",
      "having all of his semen squeezed out,",
      "he will then be swallowed whole by",
      "the huge mouth on her torso.",
      "",
      "Artist: Setouchi",
    ],
    818 => [
      "The Queen of the Dead who commands",
      "countless undead while being dead",
      "herself. She was a noble yoma",
      "necromancer when she was alive, but",
      "following her death, a forbidden",
      "technique she had used on herself",
      "allowed her to be brought back as a",
      "powerful undead. Thus Tao had been",
      "revived, and became a ruler who",
      "could control countless undead. This",
