      "becoming no different from a cripple.",
      "",
      "Artist: UN_DO",
    ],
    821 => [
      "A noble yoma from an ancient scylla",
      "species possessing both immense power",
      "and high prestige. She has",
      "established her own faction within",
      "the scylla race and her voice carries",
      "powerful influence. She is an",
      "uncompromising war hawk in contrast",
      "to the moderate Queen Scylla and",
      "while she is treated like the leader",
      "of an anti-Queen faction, she doesn't",
      "openly defy her and firmly maintains",
      "a position as her second in command.",
      "Behind the scenes however, she seems",
      "to be plotting a political move to",
      "overthrow the Queen. Additionally,",
      "the Asmodeus clan that she bears the",
      "lineage of resides in the Dark",
      "Goddess' Castle as upper class",
      "nobility.",
      "",
      "Since she is an ancient species, she",
      "possesses tremendous power rivaling",
      "that of the current Queen Scylla. She",
      "also has a very cruel personality and",
      "delights in watching others suffer,",
      "regardless of their race, age, or",
      "gender. She is extremely harsh when",
      "she rapes human males, and won't",
      "relent in torturing them until they",
      "release all of their semen and die.",
      "",
      "Artist: xelvy",
    ],
    822 => [
      "A noble yoma of the lamia lineage",
      "that is among the most prestigious",
      "in the Monster Realm who was created",
      "by Saja very early on. Most of them",
      "reside in the Dark Goddess' Castle,",
      "but some are highly ambitious and",
      "plot to ascend to the top of the",
      "lamia race. While she appears to be",
      "loyal to the moderate Queen Lamia,",
      "she is secretly plotting to steal her",
      "position. She has an extremely",
