    823 => [
      "The Sixteenth Monster Lord, whose",
      "true powers are said to rival Black",
      "Alice, who was known as the most",
      "powerful among the generations. As",
      "Monster Lord, she has entered an",
      "alliance with the Dark Goddess of",
      "the Monster Realm, and is trying to",
      "fight against the chaos phenomenon",
      "in order to avert the world's",
      "destruction. She stands in the way",
      "of Luka and his party as they enter",
      "the Dark Goddess' Castle, but it",
      "seems as if she already knows how",
      "this encounter will end.",
      "",
      "Artist: Kenkō Cross",
    ],
    824 => [
      "Saja is one of the six daughters",
      "created by the Dark Goddess",
      "herself and one of the Six",
      "Ancestors, who are the progenitors",
      "of all monsters in this world. The",
      "Six Ancestors hold the pinnacle of",
      "power and combat ability in the",
      "Monster Realm and are its sole",
      "rulers. Saja is renowned as the",
      "strongest among them, with beliefs",
      "stating that only she can face the",
      "Angelic Dominion's Micaela or",
      "Lucifina head-on. While her",
      "magical power is surpassed by",
      "Tamamo and her sexual arts by",
      "Minagi, her overall combat",
      "abilities are unmatched. Due to",
      "her immense power, she carries the",
      "title of Monster Lord, a name",
      "that, in the correct history,",
      "became synonymous with the ruler",
      "of all monsters.",
      "",
      "After the Great Monster Wars,",
      "while the other Six Ancestors were",
      "given lands by the Dark Goddess,",
      "Saja was entrusted with the",
      "continent of Hellgondo, where the",
      "Dark Goddess' castle stands. Since",
      "the continent has no human",
      "settlements, there was no need for",
      "governance, effectively making",
      "Saja the Dark Goddess' proxy ruler",
      "of the Monster Realm. Yet, as a",
      "devoted shield for the Dark",
      "Goddess, Saja never strays from",
      "her side. Among the Six Ancestors,",
      "her loyalty and devotion to the",
      "Dark Goddess as both mother and",
      "sovereign are unparalleled.",
      "",
      "Artist: Shiki",
    ],
    825 => [
      "An incarnation of darkness that",
      "serves as the opposite to the Goddess",
      "Ilias. The dark mana circulating",
      "the world coalesced into a unique",
      "ego, which reigned over the world as",
      "a higher consciousness. During the",
      "Great Monster Wars, she cornered the",
      "Goddess Ilias who was born in the",
      "same way from holy mana and attacked",
      "her, ignoring her threats to destroy",
      "the world along with herself. After",
      "having successfully defeated Ilias,",
      "the Dark Goddess Alipheese became the",
      "ruler of the world. Since then, the",
      "world came to be dominated by",
      "monsters and became known as the",
      "Monster Realm. These actions,",
      "however, greatly deviated from the",
      "true history, and the Monster Realm",
      "has had to contend with the",
      "encroachment of chaos.",
      "",
      "Artist: Naglfar",
    ],
    826 => [
      "The Dark Goddess Alipheese's chaos",
      "form, after having achieved the",
      "fusion of holy and dark power from",
      "absorbing the Angelic Dominion's",
      "Goddess Ilias. By harmonizing the",
      "holy and dark energies flowing",
      "through her body, she has gained",
      "tremendous power. However, her mind",
